import React from 'react';

interface LogoProps {
  size?: 'sm' | 'md' | 'lg' | 'xl';
  showText?: boolean;
  className?: string;
  animated?: boolean;
}

const Logo: React.FC<LogoProps> = ({ size = 'md', showText = true, className = '', animated = false }) => {
  const dimensions = {
    sm: 'w-8 h-8',
    md: 'w-10 h-10',
    lg: 'w-16 h-16',
    xl: 'w-24 h-24'
  };

  const textSize = {
    sm: 'text-lg',
    md: 'text-xl',
    lg: 'text-3xl',
    xl: 'text-4xl'
  };

  return (
    <div className={`flex items-center gap-3 ${className}`}>
      <div className={`relative flex items-center justify-center ${dimensions[size]}`}>
        <svg viewBox="0 0 100 100" className="w-full h-full drop-shadow-xl" fill="none" xmlns="http://www.w3.org/2000/svg">
          <defs>
            <linearGradient id="main_grad" x1="0" y1="0" x2="100" y2="100" gradientUnits="userSpaceOnUse">
              <stop stopColor="#1A73E8" />
              <stop offset="1" stopColor="#0D47A1" />
            </linearGradient>
            <linearGradient id="plus_grad" x1="0" y1="0" x2="100" y2="100" gradientUnits="userSpaceOnUse">
              <stop stopColor="#34A853" />
              <stop offset="1" stopColor="#1B5E20" />
            </linearGradient>
            <filter id="glow_plus" x="-20%" y="-20%" width="140%" height="140%">
              <feGaussianBlur stdDeviation="3" result="blur" />
              <feComposite in="SourceGraphic" in2="blur" operator="over" />
            </filter>
          </defs>

          {/* Background Squircle */}
          <rect x="5" y="5" width="90" height="90" rx="28" fill="url(#main_grad)" className={animated ? 'animate-pulse' : ''} />

          {/* Delivery Path Lines */}
          <path 
            d="M25 70 L45 50 L55 60 L75 35" 
            stroke="white" 
            strokeWidth="8" 
            strokeLinecap="round" 
            strokeLinejoin="round"
            className={animated ? 'animate-[dash_2s_ease-in-out_infinite]' : ''}
            style={{ strokeDasharray: 100, strokeDashoffset: animated ? 0 : 0 }}
          />

          {/* Floating Plus Accent */}
          <g filter="url(#glow_plus)">
            <circle cx="75" cy="25" r="12" fill="url(#plus_grad)" stroke="white" strokeWidth="3" />
            <path d="M75 19 V31 M69 25 H81" stroke="white" strokeWidth="3" strokeLinecap="round" />
          </g>
        </svg>
      </div>
      {showText && (
        <span className={`${textSize[size]} font-bold tracking-tight text-gray-900 font-heading`}>
          Labora<span className="text-[#34A853]">+</span>
        </span>
      )}
    </div>
  );
};

export default Logo;

