export default Dashboard;

import React from 'react';
import { LayoutDashboard, Receipt, MessageSquare, GraduationCap, Settings, LogOut, Users, FileText, Activity, Eye, EyeOff, Calculator, Zap, AlertTriangle, Wrench, Building, Navigation, Globe, X } from 'lucide-react';
import { useData } from '../contexts/DataContext';
import { UserRole } from '../types';
import Logo from './Logo';

interface SidebarProps {
  currentView: string;
  setView: (view: string) => void;
  isMobileMenuOpen: boolean;
  setIsMobileMenuOpen: (open: boolean) => void;
}

const Sidebar: React.FC<SidebarProps> = ({ currentView, setView, isMobileMenuOpen, setIsMobileMenuOpen }) => {
  const { currentUser, logout, privacyMode, togglePrivacyMode } = useData();

  const menuItems = currentUser?.role === UserRole.MANAGER 
  ? [
      { id: 'manager-dashboard', label: 'Panel Clientes', icon: Users },
      { id: 'chat-internal', label: 'Mensajería', icon: MessageSquare },
      { id: 'settings', label: 'Configuración', icon: Settings },
    ]
  : [
      { id: 'dashboard', label: 'Dashboard', icon: LayoutDashboard },
      { id: 'movements', label: 'Movimientos', icon: Activity },
      { id: 'simulator', label: 'Simulador Pro', icon: Calculator },
      { id: 'routes', label: 'Rutas', icon: Navigation },
      { id: 'documents', label: 'Documentos', icon: FileText },
      { id: 'payouts', label: 'Pagos Fast', icon: Zap },
      { id: 'education', label: 'Academia', icon: GraduationCap },
      { id: 'ai', label: 'Asistente IA', icon: MessageSquare },
      { id: 'settings', label: 'Ajustes', icon: Settings },
    ];

  const handleNavClick = (viewId: string) => {
    setView(viewId);
    setIsMobileMenuOpen(false);
  };

  return (
    <>
      {/* Mobile Sidebar Overlay */}
      <div 
        className={`fixed inset-0 bg-black/50 backdrop-blur-sm z-40 lg:hidden transition-opacity duration-300 ${isMobileMenuOpen ? 'opacity-100' : 'opacity-0 pointer-events-none'}`}
        onClick={() => setIsMobileMenuOpen(false)}
      />

      <aside className={`
        fixed lg:static inset-y-0 left-0 z-50 w-72 bg-white transform transition-all duration-300 ease-in-out lg:translate-x-0 border-r border-gray-100
        ${isMobileMenuOpen ? 'translate-x-0 shadow-2xl' : '-translate-x-full'}
      `}>
        <div className="h-full flex flex-col">

          {/* Header */}
          <div className="p-8 flex items-center justify-between">
            <Logo size="sm" />
            <button onClick={() => setIsMobileMenuOpen(false)} className="lg:hidden p-2 text-gray-400 hover:bg-gray-100 rounded-full">
               <X size={20} />
            </button>
          </div>

          {/* Navigation */}
          <nav className="flex-1 px-4 space-y-1 overflow-y-auto custom-scrollbar">
            {menuItems.map((item) => {
              const isActive = currentView === item.id;
              return (
                <button
                  key={item.id}
                  onClick={() => handleNavClick(item.id)}
                  className={`w-full flex items-center gap-4 px-4 py-3.5 rounded-2xl text-sm font-bold transition-all duration-200 group ${
                    isActive 
                      ? 'bg-[#E8F0FE] text-[#1A73E8]' 
                      : 'text-gray-500 hover:bg-gray-50 hover:text-gray-900'
                  }`}
                >
                  <item.icon size={22} className={`transition-colors ${isActive ? 'text-[#1A73E8]' : 'text-gray-400 group-hover:text-gray-600'}`} />
                  {item.label}
                </button>
              );
            })}
          </nav>

          {/* Footer / User Profile */}
          <div className="p-4 bg-gray-50/50 mt-auto">
            {/* Privacy Toggle Chip */}
            <button 
              onClick={togglePrivacyMode}
              className={`w-full flex items-center justify-center gap-2 py-3 rounded-2xl text-xs font-bold transition-all mb-4 border ${
                privacyMode 
                  ? 'bg-gray-900 text-white border-gray-900 shadow-md' 
                  : 'bg-white text-gray-600 border-gray-200 hover:bg-gray-50'
              }`}
            >
              {privacyMode ? <EyeOff size={16} /> : <Eye size={16} />}
              {privacyMode ? 'Modo Discreto' : 'Mostrar Valores'}
            </button>

            <div className="flex items-center gap-3 bg-white p-3 rounded-2xl shadow-sm border border-gray-100">
              <div className="w-10 h-10 rounded-full bg-[#1A73E8] text-white flex items-center justify-center font-bold">
                {currentUser?.name.charAt(0).toUpperCase()}
              </div>
              <div className="flex-1 min-w-0">
                <p className="text-sm font-bold text-gray-900 truncate">{currentUser?.name}</p>
                <p className="text-[10px] text-gray-400 font-bold uppercase tracking-wider">{currentUser?.role}</p>
              </div>
              <button
                onClick={logout}
                className="p-2 text-gray-300 hover:text-red-500 hover:bg-red-50 rounded-lg transition-all"
              >
                <LogOut size={18} />
              </button>
            </div>
          </div>
        </div>
      </aside>
    </>
  );
};

export default Sidebar;

import React, { useState, useRef, useEffect } from 'react';
import { Send, Bot, User as UserIcon, Loader2, Calculator, TrendingUp, AlertTriangle, Sparkles, X } from 'lucide-react';
import { getFiscalAdvice } from '../services/geminiService';

const FiscalChat: React.FC = () => {
  const [messages, setMessages] = useState<{ role: 'user' | 'model', text: string, actions?: any[] }[]>([
    { 
      role: 'model', 
      text: '¡Hola! Soy tu asistente fiscal inteligente de Labora+. ¿En qué puedo ayudarte hoy?',
      actions: [
        { label: 'Calcular IRPF', icon: Calculator, query: '¿Cuánto IRPF tengo que pagar este trimestre?' },
        { label: 'Deducir Gastos', icon: TrendingUp, query: '¿Qué gastos son deducibles si soy rider?' },
        { label: 'Riesgos Fiscales', icon: AlertTriangle, query: '¿Tengo algún riesgo fiscal?' }
      ]
    }
  ]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(scrollToBottom, [messages]);

  const handleSend = async (text: string = input) => {
    if (!text.trim()) return;

    const userMsg = text;
    setInput('');
    setMessages(prev => [...prev, { role: 'user', text: userMsg }]);
    setIsLoading(true);

    try {
      const responseText = await getFiscalAdvice(messages, userMsg);

      let actions: any[] = [];
      if (responseText.toLowerCase().includes('irpf')) {
        actions.push({ label: 'Simular Cuota', icon: Calculator, query: 'Simular cuota IRPF detallada' });
      }

      setMessages(prev => [...prev, { role: 'model', text: responseText || "Error al conectar con la IA.", actions }]);
    } catch (error) {
      setMessages(prev => [...prev, { role: 'model', text: "Lo siento, hubo un problema con la red. Inténtalo de nuevo." }]);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="h-[calc(100vh-140px)] flex flex-col bg-white rounded-[32px] shadow-2xl border border-gray-100 overflow-hidden animate-in slide-in-from-bottom-4 duration-500">
      {/* Header */}
      <div className="p-6 bg-[#1A73E8] text-white flex items-center justify-between">
        <div className="flex items-center gap-4">
          <div className="w-12 h-12 bg-white/20 backdrop-blur-md rounded-2xl flex items-center justify-center shadow-inner">
            <Sparkles size={24} className="text-white" />
          </div>
          <div>
            <h3 className="font-black text-xl tracking-tight">Asistente Labora+</h3>
            <div className="flex items-center gap-1.5">
               <div className="w-2 h-2 bg-green-400 rounded-full animate-pulse"></div>
               <span className="text-[10px] font-bold text-blue-100 uppercase tracking-widest">En línea • Gemini 2.0</span>
            </div>
          </div>
        </div>
      </div>

      {/* Message Area */}
      <div className="flex-1 overflow-y-auto p-6 space-y-8 bg-[#F8F9FA] custom-scrollbar">
        {messages.map((msg, idx) => (
          <div 
            key={idx} 
            className={`flex flex-col gap-3 ${msg.role === 'user' ? 'items-end' : 'items-start'} animate-in fade-in slide-in-from-bottom-2`}
          >
            <div className={`flex gap-3 max-w-[85%] ${msg.role === 'user' ? 'flex-row-reverse' : 'flex-row'}`}>
              <div className={`w-9 h-9 rounded-xl flex items-center justify-center flex-shrink-0 shadow-sm ${
                msg.role === 'user' ? 'bg-[#1A73E8] text-white' : 'bg-white text-[#1A73E8] border border-gray-100'
              }`}>
                {msg.role === 'user' ? <UserIcon size={18} /> : <Bot size={18} />}
              </div>
              <div className={`p-5 rounded-2xl text-sm font-medium leading-relaxed shadow-sm ${
                msg.role === 'user' 
                  ? 'bg-[#1A73E8] text-white rounded-tr-none' 
                  : 'bg-white text-gray-800 rounded-tl-none border border-gray-100'
              }`}>
                {msg.text}
              </div>
            </div>

            {/* Action Buttons */}
            {msg.actions && msg.actions.length > 0 && (
              <div className="flex flex-wrap gap-2 ml-12">
                {msg.actions.map((action: any, i: number) => (
                  <button
                    key={i}
                    onClick={() => handleSend(action.query)}
                    className="flex items-center gap-2 px-4 py-2 bg-white text-[#1A73E8] text-xs font-bold rounded-xl border border-gray-100 shadow-sm hover:bg-blue-50 transition-all active:scale-95"
                  >
                    <action.icon size={14} />
                    {action.label}
                  </button>
                ))}
              </div>
            )}
          </div>
        ))}

        {isLoading && (
          <div className="flex gap-3 animate-pulse">
            <div className="w-9 h-9 rounded-xl bg-white border border-gray-100 flex items-center justify-center text-[#1A73E8]">
              <Bot size={18} />
            </div>
            <div className="bg-white p-5 rounded-2xl rounded-tl-none shadow-sm border border-gray-100 flex items-center gap-3">
              <Loader2 size={16} className="animate-spin text-[#1A73E8]" />
              <span className="text-xs text-gray-400 font-bold uppercase tracking-widest">Consultando normativa...</span>
            </div>
          </div>
        )}
        <div ref={messagesEndRef} />
      </div>

      {/* Input Form */}
      <form 
        onSubmit={(e) => { e.preventDefault(); handleSend(); }} 
        className="p-6 bg-white border-t border-gray-100"
      >
        <div className="relative group">
          <input
            type="text"
            value={input}
            onChange={(e) => setInput(e.target.value)}
            placeholder="Haz una consulta fiscal..."
            className="w-full pl-6 pr-14 py-4 bg-gray-50 border border-gray-100 rounded-[20px] focus:outline-none focus:ring-4 focus:ring-blue-100 focus:bg-white focus:border-[#1A73E8] transition-all text-gray-800 placeholder-gray-400 font-medium"
          />
          <button 
            type="submit" 
            disabled={isLoading || !input.trim()}
            className="absolute right-2 top-1/2 -translate-y-1/2 p-3 bg-[#1A73E8] text-white rounded-2xl hover:bg-[#1557B0] disabled:opacity-30 disabled:grayscale transition-all shadow-lg shadow-blue-500/30"
          >
            <Send size={20} strokeWidth={2.5} />
          </button>
        </div>
        <p className="text-[10px] text-center text-gray-400 mt-4 font-bold uppercase tracking-widest opacity-60">
          Labora+ utiliza IA. Revisa siempre con un gestor colegiado.
        </p>
      </form>
    </div>
  );
};

export default FiscalChat;

import React, { useState } from 'react';
import { useData } from '../contexts/DataContext';
import { UserRole } from '../types';
import { Bike, Briefcase, Mail, Lock, User as UserIcon, Phone, ArrowRight, Chrome, CheckCircle2, AlertCircle, Sparkles } from 'lucide-react';
import Logo from './Logo';

const Login: React.FC = () => {
  const { login } = useData();
  const [isRegistering, setIsRegistering] = useState(false);

  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [name, setName] = useState('');
  const [role, setRole] = useState<UserRole>(UserRole.RIDER);
  const [errors, setErrors] = useState<Record<string, string>>({});

  const validate = () => {
    const newErrors: Record<string, string> = {};
    if (!email) newErrors.email = 'El correo es obligatorio';
    if (isRegistering && !name) newErrors.name = 'El nombre es obligatorio';
    if (isRegistering && password !== confirmPassword) newErrors.confirmPassword = 'Las contraseñas no coinciden';
    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (validate()) {
      login(email, role);
    }
  };

  return (
    <div className="min-h-screen bg-[#F8F9FA] flex items-center justify-center p-6 relative overflow-hidden font-sans">
      {/* Dynamic Background */}
      <div className="absolute top-[-20%] left-[-10%] w-[60%] h-[60%] bg-blue-100 rounded-full blur-[120px] opacity-40 animate-pulse"></div>
      <div className="absolute bottom-[-20%] right-[-10%] w-[60%] h-[60%] bg-green-50 rounded-full blur-[120px] opacity-40"></div>

      <div className="bg-white rounded-[40px] shadow-2xl p-10 w-full max-w-[460px] relative z-10 animate-in fade-in slide-in-from-bottom-12 duration-1000 border border-white">

