interface SavedRoute {
  id: string;
  distance: number;
  duration: number;
  baseFare: number;
  net: number;
  date: string;
}

export const RouteOptimizer: React.FC = () => {
  const config = useCountryConfig();
  const { showNotification } = useData();
  const [distance, setDistance] = useState(5);
  const [duration, setDuration] = useState(15);
  const [history, setHistory] = useState<SavedRoute[]>([]);

  // Cargar historial al montar el componente
  useEffect(() => {
    const saved = localStorage.getItem('labora_route_history');
    if (saved) {
      try {
        setHistory(JSON.parse(saved));
      } catch (e) {
        console.error("Error cargando historial de rutas");
      }
    }
  }, []);

  // Guardar historial en localStorage automáticamente al cambiar
  useEffect(() => {
    localStorage.setItem('labora_route_history', JSON.stringify(history));
  }, [history]);

  // Cálculos en tiempo real
  const baseFare = Math.max(config.min_fare, (distance * config.per_km_rate) + (duration * config.per_min_rate));
  const commission = baseFare * config.default_commission_pct;
  // Estimación de consumo (aprox 4L/100km para moto/bici eléctrica avg)
  const fuelCost = (distance * 0.04) * config.avg_fuel_price; 
  const net = baseFare - commission - fuelCost;

  const handleSaveRoute = () => {
    const newRoute: SavedRoute = {
      id: Math.random().toString(36).substr(2, 9),
      distance,
      duration,
      baseFare,
      net,
      date: new Date().toLocaleString('es-ES', { 
        day: '2-digit', 
        month: '2-digit', 
        year: 'numeric', 
        hour: '2-digit', 
        minute: '2-digit' 
      })
    };

    setHistory(prev => [newRoute, ...prev]);
    showNotification('success', 'Ruta guardada con éxito');
  };

  const clearHistory = () => {
    if(confirm('¿Estás seguro de que quieres borrar todo el historial?')) {
      setHistory([]);
      showNotification('info', 'Historial eliminado');
    }
  };

  const deleteSingleRoute = (id: string) => {
    setHistory(prev => prev.filter(r => r.id !== id));
  };

  return (
    <div className="max-w-4xl mx-auto space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500 pb-24">
      <div className="text-center">
        <h2 className="text-3xl font-black text-gray-900 flex items-center justify-center gap-3">
          <Navigation className="text-[#1A73E8]" size={32} /> 
          Optimización de Rutas
        </h2>
        <p className="text-gray-500 mt-2 font-medium">Calcula la rentabilidad real de tus trayectos antes de aceptarlos.</p>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">

        {/* Panel de Calculadora */}
        <div className="bg-white p-8 rounded-[32px] shadow-xl border border-gray-100 space-y-8 h-fit">
           <div className="flex justify-between items-center border-b border-gray-50 pb-4">
             <h3 className="font-bold text-gray-800 uppercase tracking-widest text-xs">Configuración del Trayecto</h3>
             <span className="text-[10px] bg-blue-50 px-2 py-1 rounded-lg text-[#1A73E8] font-black">{config.display_name}</span>
           </div>

           <div className="grid grid-cols-2 gap-6">
              <div>
                <label className="text-xs font-bold text-gray-400 uppercase mb-3 block">Distancia (Km)</label>
                <div className="flex items-center gap-3 bg-gray-50 p-4 rounded-2xl border border-gray-100 focus-within:ring-2 focus-within:ring-[#1A73E8] focus-within:bg-white transition-all">
                   <Navigation size={18} className="text-gray-400" />
                   <input 
                     type="number" 
                     value={distance} 
                     onChange={e => setDistance(Number(e.target.value))}
                     className="bg-transparent w-full font-bold text-xl text-gray-900 outline-none"
                     min="0.1"
                     step="0.1"
                   />
                </div>
              </div>
              <div>
                <label className="text-xs font-bold text-gray-400 uppercase mb-3 block">Duración (Min)</label>
                <div className="flex items-center gap-3 bg-gray-50 p-4 rounded-2xl border border-gray-100 focus-within:ring-2 focus-within:ring-[#1A73E8] focus-within:bg-white transition-all">
                   <Clock size={18} className="text-gray-400" />
                   <input 
                     type="number" 
                     value={duration} 
                     onChange={e => setDuration(Number(e.target.value))}
                     className="bg-transparent w-full font-bold text-xl text-gray-900 outline-none"
                     min="1"
                   />
                </div>
              </div>
           </div>

           <div className="pt-4 space-y-4">
              <div className="flex justify-between items-center text-sm font-medium">
                 <span className="text-gray-500">Tarifa Estimada</span>
                 <span className="text-gray-900 font-bold">{baseFare.toFixed(2)} {config.currency_symbol}</span>
              </div>
              <div className="flex justify-between items-center text-sm text-red-500 font-medium">
                 <span>Comisión App ({(config.default_commission_pct * 100).toFixed(0)}%)</span>
                 <span>-{commission.toFixed(2)} {config.currency_symbol}</span>
              </div>

              <div className="bg-[#1A1A1A] text-white p-6 rounded-[24px] shadow-2xl relative overflow-hidden group">
                 <div className="relative z-10 flex justify-between items-center">
                    <div>
                      <p className="text-gray-400 text-[10px] font-black uppercase tracking-widest mb-1">Beneficio Neto</p>
                      <span className={`text-4xl font-black ${net > 0 ? 'text-[#2ECC71]' : 'text-red-400'}`}>
                        {net.toFixed(2)}<span className="text-lg ml-1 font-normal opacity-60">{config.currency_symbol}</span>
                      </span>
                    </div>
                    <div className={`p-4 rounded-2xl ${net > 0 ? 'bg-green-500/20' : 'bg-red-500/20'}`}>
                       <DollarSign size={28} className={net > 0 ? 'text-[#2ECC71]' : 'text-red-400'} />
                    </div>
                 </div>
                 <div className="absolute top-0 right-0 w-32 h-32 bg-white/5 rounded-full blur-3xl group-hover:scale-150 transition-transform duration-700"></div>
              </div>
           </div>

           <button 
             onClick={handleSaveRoute}
             className="w-full py-5 bg-[#1A73E8] text-white font-black text-sm uppercase tracking-widest rounded-2xl shadow-xl shadow-blue-500/20 hover:bg-[#1557B0] hover:scale-[1.02] active:scale-95 transition-all flex items-center justify-center gap-3"
           >
             <Save size={20} strokeWidth={2.5} /> Guardar en Historial
           </button>
        </div>

        {/* Panel de Historial */}
        <div className="space-y-4">
           <div className="flex justify-between items-center px-2">
             <h3 className="font-black text-gray-900 flex items-center gap-2">
               <History size={20} className="text-gray-400" /> Historial Reciente
             </h3>
             {history.length > 0 && (
               <button 
                 onClick={clearHistory} 
                 className="text-[10px] text-red-500 font-black uppercase tracking-widest hover:underline px-3 py-1 hover:bg-red-50 rounded-lg transition-all"
               >
                 Borrar Todo
               </button>
             )}
           </div>

           <div className="space-y-4 max-h-[550px] overflow-y-auto pr-2 custom-scrollbar">
             {history.length === 0 ? (
               <div className="text-center py-20 bg-gray-50/50 rounded-[32px] border-2 border-dashed border-gray-100">
                 <div className="w-16 h-16 bg-white rounded-2xl shadow-sm flex items-center justify-center mx-auto mb-4">
                    <MapPin size={32} className="text-gray-200" />
                 </div>
                 <p className="text-gray-400 font-bold text-sm">No hay rutas guardadas aún.</p>
                 <p className="text-gray-300 text-xs mt-1">Tus cálculos aparecerán aquí.</p>
               </div>
             ) : (
               history.map(item => (
                  <div key={item.id} className="bg-white p-5 rounded-[24px] border border-gray-100 hover:shadow-lg hover:border-blue-100 transition-all group animate-in slide-in-from-right-4">
                     <div className="flex justify-between items-start mb-4">
                        <div className="flex items-center gap-2 text-gray-400 text-[10px] font-black uppercase tracking-tighter">
                           <Calendar size={12} /> {item.date}
                        </div>
                        <button 
                          onClick={() => deleteSingleRoute(item.id)} 
                          className="text-gray-300 hover:text-red-500 p-1 rounded-lg hover:bg-red-50 transition-colors"
                        >
                          <Trash2 size={16} />
                        </button>
                     </div>
                     <div className="flex justify-between items-end">
                        <div className="space-y-1">
                           <div className="flex items-center gap-3">
                              <span className="text-lg font-black text-gray-800">{item.distance} <span className="text-xs text-gray-400 font-bold uppercase">Km</span></span>
                              <ArrowRight size={14} className="text-gray-300" />
                              <span className="text-lg font-black text-gray-800">{item.duration} <span className="text-xs text-gray-400 font-bold uppercase">Min</span></span>
                           </div>
                           <p className="text-[10px] text-gray-400 font-bold uppercase tracking-wider">
                             Tarifa Base: {item.baseFare.toFixed(2)}{config.currency_symbol}
                           </p>
                        </div>
                        <div className={`text-2xl font-black ${item.net > 0 ? 'text-[#2ECC71]' : 'text-red-500'}`}>
                           {item.net > 0 ? '+' : ''}{item.net.toFixed(2)}<span className="text-xs ml-1 font-bold">{config.currency_symbol}</span>
                        </div>
                     </div>
                  </div>
               ))
             )}
           </div>
        </div>

      </div>

      {/* Tip Pro */}
      <div className="bg-blue-50/50 p-6 rounded-[28px] border border-blue-100 flex items-start gap-4">
         <div className="p-3 bg-white rounded-2xl shadow-sm">
            <Fuel size={24} className="text-[#1A73E8]" />
         </div>
         <div>
            <h4 className="font-bold text-blue-900 text-sm mb-1">Ahorro de Combustible</h4>
            <p className="text-xs text-blue-800 leading-relaxed font-medium">
               Recuerda que Labora+ descuenta automáticamente el coste estimado de gasolina ({config.avg_fuel_price} {config.currency_symbol}/L) para darte un beneficio real "limpio" en mano.
            </p>
         </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { useData } from '../contexts/DataContext';
import { ChevronLeft, ChevronRight, Calendar as CalendarIcon, CheckCircle, Clock, ArrowRight, HelpCircle, FileText, Bell, Plus, Save, X, Download, Printer, Share2 } from 'lucide-react';
import { Payment } from '../types';

const Calendar: React.FC = () => {
  const { payments, markPaymentAsReceived, addPayment, currentUser } = useData();
  const [currentDate, setCurrentDate] = useState(new Date());
  const [selectedDate, setSelectedDate] = useState<string | null>(null);
  const [viewingInvoice, setViewingInvoice] = useState<Payment | null>(null);

  // Manual Entry State
  const [isAddingManual, setIsAddingManual] = useState(false);
  const [manualForm, setManualForm] = useState({
    platform: '',
    amount: ''
  });

  // Calendar Logic
  const daysInMonth = new Date(currentDate.getFullYear(), currentDate.getMonth() + 1, 0).getDate();
  const firstDayOfMonth = new Date(currentDate.getFullYear(), currentDate.getMonth(), 1).getDay(); // 0 = Sun

  // Adjust for Monday start (EU standard)
  const startingSlot = firstDayOfMonth === 0 ? 6 : firstDayOfMonth - 1;

  const monthNames = ["Enero", "Febrero", "Marzo", "Abril", "Mayo", "Junio", "Julio", "Agosto", "Septiembre", "Octubre", "Noviembre", "Diciembre"];
  const weekDays = ["L", "M", "X", "J", "V", "S", "D"];

  const prevMonth = () => {
    setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() - 1, 1));
  };

  const nextMonth = () => {
    setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() + 1, 1));
  };

  // Group payments by date
  const paymentsByDate = useMemo(() => {
    const map: Record<string, Payment[]> = {};
    payments.forEach(p => {
      if (!map[p.date]) map[p.date] = [];
      map[p.date].push(p);
    });
    return map;
  }, [payments]);

  // Derived selected payments based on selectedDate
  const selectedPayments = useMemo(() => {
    if (!selectedDate) return [];
    return paymentsByDate[selectedDate] || [];
  }, [selectedDate, paymentsByDate]);

  const handleDayClick = (day: number) => {
    const dateStr = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
    setSelectedDate(dateStr);
    setIsAddingManual(false); // Reset manual mode
  };

  const closeModal = () => {
    setSelectedDate(null);
    setIsAddingManual(false);
    setManualForm({ platform: '', amount: '' });
  };

  const handleSaveManual = (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedDate || !manualForm.platform || !manualForm.amount) return;

    addPayment({
      platform: manualForm.platform,
      amount: parseFloat(manualForm.amount),
      date: selectedDate,
      status: 'pending',
      estimated: true,
      domain: 'generic' // Placeholder
    });

    // Reset form but keep modal open to see new item
    setIsAddingManual(false);
    setManualForm({ platform: '', amount: '' });
  };

  // Calculate monthly stats
  const monthlyStats = useMemo(() => {
    const currentMonthStr = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}`;
    const monthPayments = payments.filter(p => p.date.startsWith(currentMonthStr));

    const received = monthPayments.filter(p => p.status === 'received').reduce((acc, curr) => acc + curr.amount, 0);
    const pending = monthPayments.filter(p => p.status === 'pending').reduce((acc, curr) => acc + curr.amount, 0);

    return { received, pending };
  }, [payments, currentDate]);

  const renderCalendarDays = () => {
    const days = [];

    // Empty slots for prev month
    for (let i = 0; i < startingSlot; i++) {
      days.push(<div key={`empty-${i}`} className="h-24 bg-gray-50/30 border-b border-r border-gray-100"></div>);
    }

    // Days
    for (let d = 1; d <= daysInMonth; d++) {
      const dateStr = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
      const dayPayments = paymentsByDate[dateStr] || [];
      const isToday = new Date().toISOString().split('T')[0] === dateStr;

      days.push(
        <div 
          key={d} 
          onClick={() => handleDayClick(d)}
          className={`h-24 border-b border-r border-gray-100 p-1 relative cursor-pointer hover:bg-blue-50 transition-colors ${isToday ? 'bg-blue-50/50' : 'bg-white'}`}
        >
          <span className={`text-sm font-medium p-1 rounded-full w-7 h-7 flex items-center justify-center ${isToday ? 'bg-[#2D6CDF] text-white shadow-md' : 'text-gray-500'}`}>
            {d}
          </span>

          {/* Payment Indicators */}
          <div className="flex flex-wrap gap-1 mt-1 content-start">
            {dayPayments.map((p, idx) => (
              <div key={idx} className="relative group/tooltip">
                <div className={`w-6 h-6 rounded-full flex items-center justify-center shadow-sm border ${p.status === 'received' ? 'bg-green-100 border-green-200' : 'bg-yellow-100 border-yellow-200 dashed border-2'}`}>
                   <img 
                     src={`https://logo.clearbit.com/${p.domain}`} 
                     className="w-4 h-4 object-contain rounded-full"
                     onError={(e) => {
                        const target = e.target as HTMLImageElement;
                        const parent = target.parentElement;
                        if (parent) {
                           target.style.display = 'none';
                           parent.innerHTML = `<span class="text-[8px] font-bold ${p.status === 'received' ? 'text-green-700' : 'text-yellow-700'}">${p.platform[0]}</span>`;
                        }
                     }}
                   />
                </div>
              </div>
            ))}
          </div>
        </div>
      );
    }
    return days;
  };

  return (
    <div className="space-y-6 pb-20 lg:pb-0 animate-in fade-in slide-in-from-bottom-4 duration-500 relative">
      <div className="flex justify-between items-end">
        <div>
          <h2 className="text-3xl font-bold text-[#1A1A1A]">Calendario</h2>
          <p className="text-gray-500 mt-1">Controla tus fechas de cobro</p>
        </div>
        <div className="hidden md:block text-right">
          <p className="text-xs text-gray-400 font-bold uppercase">Total Pendiente (Mes)</p>
          <p className="text-xl font-bold text-[#F1C40F]">{monthlyStats.pending.toFixed(2)} €</p>
        </div>
      </div>

      {/* Calendar Container */}
      <div className="bg-white rounded-[24px] shadow-sm border border-gray-100 overflow-hidden">

        {/* Header Controls */}
        <div className="p-6 flex items-center justify-between border-b border-gray-100">
          <button onClick={prevMonth} className="p-2 hover:bg-gray-100 rounded-full text-gray-600 transition-colors">
            <ChevronLeft size={24} />
          </button>
          <div className="text-center">
            <h3 className="text-xl font-bold text-gray-900 capitalize">{monthNames[currentDate.getMonth()]} {currentDate.getFullYear()}</h3>
            <p className="text-xs text-gray-400 font-medium uppercase tracking-widest mt-1">Vista Mensual</p>
          </div>
          <button onClick={nextMonth} className="p-2 hover:bg-gray-100 rounded-full text-gray-600 transition-colors">
            <ChevronRight size={24} />
          </button>
        </div>

        {/* Days Header */}
        <div className="grid grid-cols-7 bg-gray-50 border-b border-gray-100">
          {weekDays.map(day => (
            <div key={day} className="py-3 text-center text-xs font-bold text-gray-400 uppercase">
              {day}
            </div>
          ))}
        </div>

        {/* Calendar Grid */}
        <div className="grid grid-cols-7">
          {renderCalendarDays()}
        </div>
      </div>

      {/* Monthly Summary Mobile */}
      <div className="md:hidden grid grid-cols-2 gap-4">
         <div className="bg-green-50 p-4 rounded-2xl border border-green-100">
            <p className="text-xs text-green-600 font-bold uppercase">Recibido</p>
            <p className="text-lg font-bold text-green-800">{monthlyStats.received.toFixed(0)} €</p>
         </div>
         <div className="bg-yellow-50 p-4 rounded-2xl border border-yellow-100">
            <p className="text-xs text-yellow-600 font-bold uppercase">Pendiente</p>
            <p className="text-lg font-bold text-yellow-800">{monthlyStats.pending.toFixed(0)} €</p>
         </div>
      </div>

      {/* Detail Modal */}
      {selectedDate && (
        <div 
          className="fixed inset-0 bg-black/60 backdrop-blur-sm z-50 flex items-center justify-center p-4 animate-in fade-in duration-200"
          onClick={closeModal}
        >
          <div 
            className="bg-white rounded-[24px] w-full max-w-md shadow-2xl overflow-hidden animate-in slide-in-from-bottom-10 duration-300" 
            onClick={e => e.stopPropagation()}
          >
            <div className="bg-[#2D6CDF] p-6 text-white relative">
              <div className="flex items-center gap-3 mb-1">
                <CalendarIcon size={20} className="text-blue-200" />
                <h3 className="text-xl font-bold">{new Date(selectedDate).toLocaleDateString('es-ES', { weekday: 'long', day: 'numeric', month: 'long' })}</h3>
              </div>
              <p className="text-blue-100 text-sm">
                {selectedPayments.length > 0 ? `${selectedPayments.length} pagos programados` : 'Sin actividad registrada'}
              </p>
              <button 
                onClick={closeModal}
                className="absolute top-4 right-4 p-2 bg-white/10 hover:bg-white/20 rounded-full transition-colors"
              >
                <ChevronRight size={20} className="rotate-90" />
              </button>
            </div>

            <div className="p-6 space-y-4 max-h-[60vh] overflow-y-auto">

              {/* Render Payments List */}
              {selectedPayments.length > 0 && !isAddingManual && (
                selectedPayments.map(p => (
                  <div key={p.id} className="bg-white border border-gray-100 rounded-2xl p-4 shadow-sm relative group">
                    <div className="flex justify-between items-start mb-3">
                      <div className="flex items-center gap-3">
                        <div className="w-10 h-10 rounded-xl border border-gray-100 p-1 flex items-center justify-center">
                           <img 
                             src={`https://logo.clearbit.com/${p.domain}`} 
                             className="w-full h-full object-contain"
                             onError={(e) => {
                                const target = e.target as HTMLImageElement;
                                const parent = target.parentElement;
                                if (parent) {
                                   target.style.display = 'none';
                                   parent.innerHTML = `<span class="text-sm font-bold text-gray-500">${p.platform[0]}</span>`;
                                   parent.className += " bg-gray-50";
                                }
                             }}
                           />
                        </div>
                        <div>
                          <h4 className="font-bold text-gray-900">{p.platform}</h4>
                          <div className="flex items-center gap-1">
                            <span className={`text-xs font-bold px-2 py-0.5 rounded-full ${p.status === 'received' ? 'bg-green-100 text-green-700' : 'bg-yellow-100 text-yellow-700'}`}>
                              {p.status === 'received' ? 'Recibido' : 'Pendiente'}
                            </span>
                            {p.estimated && <span className="text-xs text-gray-400 italic">(Est.)</span>}
                          </div>
                        </div>
                      </div>
                      <p className="text-lg font-bold text-gray-900">{p.amount.toFixed(2)} €</p>
                    </div>

                    {/* Actions */}
                    <div className="grid grid-cols-2 gap-2 mt-4">
                      {p.status === 'pending' ? (
                        <button 
                          onClick={() => {
                             markPaymentAsReceived(p.id);
                          }}
                          className="flex items-center justify-center gap-2 py-2 bg-[#2ECC71] text-white rounded-xl text-xs font-bold hover:bg-green-600 transition-colors shadow-lg shadow-green-500/20"
                        >
                          <CheckCircle size={14} /> Confirmar Cobro
                        </button>
                      ) : (
                        <button className="flex items-center justify-center gap-2 py-2 bg-gray-100 text-gray-500 rounded-xl text-xs font-bold cursor-default">
                          <CheckCircle size={14} /> Cobrado
                        </button>
                      )}

                      <button 
                        onClick={() => setViewingInvoice(p)}
                        className="flex items-center justify-center gap-2 py-2 bg-blue-50 text-[#2D6CDF] rounded-xl text-xs font-bold hover:bg-blue-100 transition-colors"
                      >
                        <FileText size={14} /> Ver Factura
                      </button>
                    </div>
                  </div>
                ))
              )}

              {/* Empty State or Manual Form */}
              {selectedPayments.length === 0 && !isAddingManual && (
                <div className="text-center py-8 text-gray-400">
                  <Clock size={48} className="mx-auto mb-3 opacity-20" />
                  <p>No hay pagos para este día.</p>
                </div>
              )}

              {/* Manual Entry Form */}
              {isAddingManual ? (
                <form onSubmit={handleSaveManual} className="bg-gray-50 p-4 rounded-2xl border border-gray-200 animate-in fade-in slide-in-from-bottom-2">
                   <div className="flex justify-between items-center mb-4">
                     <h4 className="font-bold text-gray-700">Nuevo Pago Previsto</h4>
                     <button type="button" onClick={() => setIsAddingManual(false)} className="text-gray-400 hover:text-gray-600"><X size={18} /></button>
                   </div>
                   <div className="space-y-3">
                      <div>
                        <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Plataforma / Cliente</label>
                        <input 
                          type="text"
                          placeholder="Ej: Uber, Cliente Particular..."
                          className="w-full p-2 border rounded-lg text-sm focus:ring-2 focus:ring-blue-500 outline-none"
                          value={manualForm.platform}
                          onChange={e => setManualForm({...manualForm, platform: e.target.value})}
                          required
                        />
                      </div>
                      <div>
                        <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Importe Estimado (€)</label>
                        <input 
                          type="number"
                          placeholder="0.00"
                          step="0.01"
                          className="w-full p-2 border rounded-lg text-sm focus:ring-2 focus:ring-blue-500 outline-none"
                          value={manualForm.amount}
                          onChange={e => setManualForm({...manualForm, amount: e.target.value})}
                          required
                        />
                      </div>
                      <button 
                        type="submit"
                        className="w-full bg-[#2D6CDF] text-white py-2.5 rounded-xl font-bold text-sm hover:bg-blue-700 transition-colors flex items-center justify-center gap-2 mt-2"
                      >
                        <Save size={16} /> Guardar Previsión
                      </button>
                   </div>
                </form>
              ) : (
                 <button 
                  onClick={() => setIsAddingManual(true)}
                  className="w-full mt-4 text-[#2D6CDF] font-bold text-sm flex items-center justify-center gap-2 py-3 rounded-xl border border-dashed border-blue-200 hover:bg-blue-50 transition-all"
                 >
                  <Plus size={16} /> Añadir previsión manual
                </button>
              )}

            </div>

