}

export interface Payment {
  id: string;
  platform: string; // 'Uber', 'Glovo', etc.
  amount: number;
  date: string; // YYYY-MM-DD
  status: 'pending' | 'received';
  estimated: boolean;
  domain?: string; // for logo
}

export interface Notification {
  id: string;
  type: 'success' | 'error' | 'info';
  message: string;
}

import React, { createContext, useContext, useState, useEffect, ReactNode, PropsWithChildren } from 'react';
import { User, Income, Expense, Document, UserRole, FiscalSummary, Payment, Notification, Vehicle } from '../types';

interface DataContextType {
  currentUser: User | null;
  users: User[];
  incomes: Income[];
  expenses: Expense[];
  documents: Document[];
  payments: Payment[];
  vehicle: Vehicle | null;
  hasOnboarded: boolean;
  privacyMode: boolean;
  darkMode: boolean;
  notifications: Notification[];
  togglePrivacyMode: () => void;
  toggleDarkMode: () => void;
  completeOnboarding: () => void;
  login: (email: string, role: UserRole) => void;
  logout: () => void;
  updateUserConfig: (platforms: string[], banks: string[]) => void;
  addIncome: (income: Omit<Income, 'id' | 'userId'>) => void;
  addIncomes: (incomes: Omit<Income, 'id' | 'userId'>[]) => void;
  addExpense: (expense: Omit<Expense, 'id' | 'userId'>) => void;
  addExpenses: (expenses: Omit<Expense, 'id' | 'userId'>[]) => void;
  updateExpense: (expense: Expense) => void;
  addDocument: (doc: Omit<Document, 'id' | 'userId'>) => void;
