    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h2 className="text-3xl font-bold text-[#1A1A1A] flex items-center gap-2">
            <Plug className="text-purple-500" /> Integraciones
          </h2>
          <p className="text-gray-500 mt-1">Conecta herramientas externas compatibles con {selectedCountry.display_name}.</p>
        </div>

        <div className="relative">
           <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
           <input 
             type="text" 
             placeholder="Buscar integración..."
             value={searchTerm}
             onChange={e => setSearchTerm(e.target.value)}
             className="pl-10 pr-4 py-2.5 bg-white border border-gray-200 rounded-xl shadow-sm focus:ring-2 focus:ring-purple-500 outline-none w-64"
           />
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
         {filtered.map(int => (
            <div key={int.id} className="bg-white p-6 rounded-[24px] border border-gray-100 shadow-sm hover:shadow-md transition-all flex flex-col justify-between h-48">
               <div className="flex justify-between items-start">
                  <div className="w-14 h-14 bg-gray-50 rounded-2xl p-2 flex items-center justify-center border border-gray-100">
                     <img 
                       src={`https://logo.clearbit.com/${int.logo_url}`} 
                       className="w-full h-full object-contain"
                       onError={(e) => {
                          const t = e.target as HTMLImageElement;
                          t.style.display = 'none';
                       }}
                     />
                     <div className="hidden w-full h-full flex items-center justify-center font-bold text-gray-400 text-xs">IMG</div>
                  </div>
                  <span className={`px-2 py-1 rounded-lg text-[10px] font-bold uppercase ${int.type === 'delivery' ? 'bg-orange-50 text-orange-600' : 'bg-blue-50 text-blue-600'}`}>
                    {int.type}
                  </span>
               </div>

               <div>
                  <h3 className="font-bold text-lg text-gray-900">{int.name}</h3>
                  <div className="flex items-center gap-2 mt-3">
                     {int.is_installed ? (
                        <button className="flex-1 py-2 bg-green-50 text-green-700 rounded-xl text-sm font-bold flex items-center justify-center gap-2 cursor-default">
                           <Check size={16} /> Activo
                        </button>
                     ) : (
                        <button className="flex-1 py-2 bg-[#1A1A1A] text-white rounded-xl text-sm font-bold flex items-center justify-center gap-2 hover:bg-black transition-colors">
                           <Plus size={16} /> Conectar
                        </button>
                     )}
                  </div>
               </div>
            </div>
         ))}

         {filtered.length === 0 && (
            <div className="col-span-3 py-12 text-center text-gray-400 bg-gray-50 rounded-[24px] border-2 border-dashed border-gray-200">
               <AlertCircle className="mx-auto mb-2 opacity-50" size={32} />
               <p>No se encontraron integraciones compatibles.</p>
            </div>
         )}
      </div>
    </div>
  );
};

