            <div className="flex items-center gap-3 bg-white p-3 rounded-[20px] shadow-sm border border-gray-100 hover:shadow-md transition-shadow cursor-pointer">
              <div className="w-10 h-10 rounded-full bg-gradient-to-tr from-blue-500 to-cyan-400 text-white flex items-center justify-center font-bold text-lg shadow-md">
                {currentUser?.name.charAt(0).toUpperCase()}
              </div>
              <div className="flex-1 min-w-0">
                <p className="text-sm font-bold text-gray-900 truncate">{currentUser?.name}</p>
                <p className="text-[10px] text-gray-400 font-bold uppercase tracking-wider">{currentUser?.role}</p>
