import { GoogleGenAI, Type } from "@google/genai";
import { ExpenseCategory } from '../types';
import { CountryConfig } from '../modules/country-config/types';

// Initialize Gemini Client
// NOTE: API Key is expected to be in process.env.API_KEY
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

/**
 * Analyze a receipt image to extract date, amount, category, and merchant.
 */
export const analyzeReceipt = async (base64Image: string): Promise<{ merchantName: string; date: string; amount: number; category: string; summary: string }> => {
  try {
    // Using gemini-2.5-flash for fast and accurate vision-to-json extraction
    const modelId = "gemini-2.5-flash";

    const categoryList = Object.values(ExpenseCategory).join(", ");

    const response = await ai.models.generateContent({
      model: modelId,
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: "image/jpeg",
              data: base64Image,
            },
          },
          {
            text: `Eres un asistente contable experto y un sistema OCR de alta precisión. Analiza la imagen de este ticket o factura.

            Extrae la siguiente información estructurada:
            1. **merchantName**: Nombre del comercio o proveedor (ej. Repsol, Mercadona). Si no es visible, usa "Comercio Desconocido".
            2. **date**: Fecha de emisión en formato ISO estricto (YYYY-MM-DD). Si el año no está claro, asume el año actual. Si no encuentras fecha, usa la fecha de hoy.
            3. **amount**: Importe total (TOTAL a pagar). Devuelve solo el número (ej. 45.50).
            4. **category**: Clasifica el gasto en EXACTAMENTE una de estas categorías: [${categoryList}].
               - Gasolina: Estaciones de servicio, combustible.
               - Mantenimiento: Talleres, reparaciones, piezas.
               - Comida: Restaurantes, supermercados (si es dieta).
               - Móvil: Facturas de teléfono/internet.
               - Cuota Autónomo: Seguridad Social.
               - Equipamiento: Ropa, casco, mochila, soporte móvil.
               - Si no encaja en ninguna, usa estrictamente "Otros".
            5. **summary**: Breve descripción del gasto (ej. "Llenado depósito", "Cambio aceite", "Menú mediodía").

            Responde únicamente con el objeto JSON.`
          },
        ],
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            merchantName: { type: Type.STRING, description: "Nombre del comercio" },
            date: { type: Type.STRING, description: "Fecha YYYY-MM-DD" },
            amount: { type: Type.NUMBER, description: "Importe total" },
            category: { type: Type.STRING, enum: Object.values(ExpenseCategory) },
            summary: { type: Type.STRING, description: "Resumen corto" }
          },
          required: ["merchantName", "date", "amount", "category", "summary"]
        }
      }
    });

    const text = response.text;
    if (!text) throw new Error("No response from AI");
    return JSON.parse(text);

  } catch (error) {
    console.error("Error analyzing receipt:", error);
    throw error;
  }
};

/**
