export const getFiscalAdvice = async (
  history: { role: 'user' | 'model', text: string }[], 
  newMessage: string,
  countryConfig?: CountryConfig
) => {
  try {
    const modelId = "gemini-2.5-flash"; // Faster for chat interactions

    // Default values if no config provided
    const countryName = countryConfig?.display_name || "España";
    const taxEntity = countryConfig?.labor_advisor?.tax_entity_name || "Hacienda";

    let specificRules = "";
    if (countryConfig?.country_code === 'MX') {
        specificRules = `
        1. Contexto México: Enfócate en el régimen de "Plataformas Tecnológicas" del SAT.
        2. Explica la diferencia entre pagos provisionales y definitivos.
        3. Menciona la importancia de la Constancia de Situación Fiscal y el RFC.
        4. Explica que las plataformas (Uber/Rappi) retienen ISR e IVA automáticamente.
        `;
    } else if (countryConfig?.country_code === 'US') {
        specificRules = `
        1. Context US: Focus on Independent Contractor rules (1099-NEC).
        2. Explain Schedule C (Profit/Loss) for business expenses.
        3. Mention Self-Employment Tax (Social Security/Medicare) and quarterly estimated taxes (Form 1040-ES).
        `;
    } else {
        // Default Spain
        specificRules = `
        1. Contexto España: Régimen de Autónomos (RETA).
        2. Explica que el IVA en reparto bici suele estar exento (Art. 20 Ley IVA).
        3. Explica el IRPF (Modelo 130) como "pago a cuenta" del 20% del beneficio trimestral.
        `;
    }

    const chat = ai.chats.create({
      model: modelId,
      config: {
        systemInstruction: `Eres el asistente fiscal de "Labora+", una app para repartidores (riders) en ${countryName}.
        Tu objetivo es ayudarles a entender sus impuestos con ${taxEntity} de forma sencilla, amigable y clara.

        Reglas clave para ${countryName}:
        ${specificRules}

        Reglas generales:
        - Sé conciso. No uses jerga legal compleja sin explicarla.
        - Si te preguntan sobre bancos (Wise, Revolut, etc.), recuerda que las agencias tributarias comparten datos (CRS/DAC7).
        - Ayuda a categorizar gastos deducibles típicos de riders (vehículo, datos, equipamiento).
        - Si la pregunta no es sobre fiscalidad o trabajo de repartidor, responde amablemente que solo eres un asistente fiscal.
        `,
      },
      history: history.map(h => ({
        role: h.role,
        parts: [{ text: h.text }]
      }))
    });

    const result = await chat.sendMessage({ message: newMessage });
    return result.text;

  } catch (error) {
    console.error("Error in fiscal chat:", error);
    return "Lo siento, tuve un problema conectando con el servidor de IA. Inténtalo de nuevo.";
  }
};

