      </div>

      {/* Advanced Filters */}
      <div className="bg-white p-5 rounded-[24px] border border-gray-100 shadow-sm space-y-4">
        <div className="flex items-center gap-2 text-gray-500 text-sm font-bold uppercase tracking-wider mb-2">
