           <div className="absolute bottom-0 left-0 w-full h-1/3 bg-blue-50/50"></div>
           <div className={`font-heading font-black bg-gradient-to-br from-blue-700 to-emerald-600 bg-clip-text text-transparent flex items-start leading-none ${size === 'xl' ? 'text-3xl' : size === 'lg' ? 'text-2xl' : 'text-xl'}`}>
