          {size !== 'sm' && (
            <span className={`text-xs font-medium uppercase tracking-widest ${variant === 'dark' ? 'text-slate-400' : 'text-slate-400'} scale-90 origin-left`}>
              Enterprise
            </span>
          )}
        </div>
      )}
    </div>
  );
};

