    { id: 'int_4', name: 'Quickbooks', type: 'accounting', logo_url: 'quickbooks.intuit.com', status: 'active', country_codes: ['US', 'GB'], is_installed: false },
    { id: 'int_5', name: 'Holded', type: 'accounting', logo_url: 'holded.com', status: 'active', country_codes: ['ES'], is_installed: true },
    { id: 'int_6', name: 'Revolut Business', type: 'banking', logo_url: 'revolut.com', status: 'active', country_codes: ['ES', 'GB'], is_installed: true },
  ];

  const filtered = integrations.filter(i => 
    i.name.toLowerCase().includes(searchTerm.toLowerCase()) && 
    (i.country_codes.includes(selectedCountry.country_code) || i.country_codes.length === 0)
  );

  // Logo Placeholder Component
  const IntegrationLogo = ({ url, name, type }: { url: string, name: string, type: string }) => {
    const [error, setError] = useState(false);

    if (error) {
      // Fallback UI
      let Icon = Package;
      let bgClass = "bg-blue-50 text-blue-600";

      if (type === 'banking') { Icon = Building2; bgClass = "bg-purple-50 text-purple-600"; }
      if (type === 'accounting') { Icon = FileText; bgClass = "bg-orange-50 text-orange-600"; }

      return (
        <div className={`w-14 h-14 rounded-xl flex items-center justify-center ${bgClass} border border-slate-100 shadow-sm`}>
           <span className="text-xs font-bold uppercase">{name.substring(0,2)}</span>
        </div>
      );
    }

    return (
      <div className="w-14 h-14 bg-white rounded-xl p-2 flex items-center justify-center border border-slate-100 shadow-sm relative group overflow-hidden">
         <img 
           src={`https://logo.clearbit.com/${url}`} 
           className="w-full h-full object-contain relative z-10 transition-transform group-hover:scale-110"
           alt={name}
           onError={() => setError(true)}
         />
         <div className="absolute inset-0 bg-slate-50 opacity-0 group-hover:opacity-50 transition-opacity"></div>
      </div>
    );
  };

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4">

      {/* Header */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 bg-white p-6 rounded-2xl border border-slate-200 shadow-sm">
        <div>
          <h2 className="text-2xl font-bold text-slate-900 flex items-center gap-2">
            <Plug className="text-blue-600" size={24} /> Marketplace de Integraciones
          </h2>
          <p className="text-slate-500 mt-1 text-sm">Conecta tus herramientas operativas para sincronización automática.</p>
        </div>

        <div className="relative group">
           <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-blue-500 transition-colors" size={18} />
           <input 
             type="text" 
             placeholder="Buscar app o servicio..."
             value={searchTerm}
             onChange={e => setSearchTerm(e.target.value)}
             className="pl-10 pr-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm focus:ring-2 focus:ring-blue-500 focus:bg-white outline-none w-full md:w-64 transition-all"
           />
        </div>
      </div>

      {/* Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
         {filtered.map(int => (
            <div key={int.id} className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm hover-card flex flex-col justify-between h-48 group cursor-pointer">

               <div className="flex justify-between items-start">
                  <IntegrationLogo url={int.logo_url} name={int.name} type={int.type} />

                  <span className={`px-2.5 py-1 rounded-full text-[10px] font-bold uppercase tracking-wide border ${
                    int.type === 'delivery' ? 'bg-orange-50 text-orange-700 border-orange-100' : 
                    int.type === 'banking' ? 'bg-purple-50 text-purple-700 border-purple-100' : 
                    'bg-blue-50 text-blue-700 border-blue-100'
                  }`}>
                    {int.type}
                  </span>
               </div>

               <div>
                  <div className="flex justify-between items-end">
                    <h3 className="font-bold text-lg text-slate-900 group-hover:text-blue-600 transition-colors">{int.name}</h3>
                    <ArrowUpRight size={16} className="text-slate-300 group-hover:text-blue-500 transition-colors mb-1" />
                  </div>

                  <div className="flex items-center gap-2 mt-4 pt-4 border-t border-slate-50">
                     {int.is_installed ? (
                        <button className="w-full py-2 bg-emerald-50 text-emerald-700 border border-emerald-100 rounded-lg text-xs font-bold flex items-center justify-center gap-2 cursor-default">
                           <Check size={14} /> Instalada
                        </button>
                     ) : (
                        <button className="w-full py-2 bg-slate-900 text-white rounded-lg text-xs font-bold flex items-center justify-center gap-2 hover:bg-slate-800 transition-colors shadow-lg shadow-slate-200">
                           <Plus size={14} /> Conectar
                        </button>
                     )}
                  </div>
               </div>
            </div>
         ))}
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { DataProvider, useData } from './contexts/DataContext';
import { CountryProvider } from './contexts/CountryContext'; 
import { OrganizationProvider } from './contexts/OrganizationContext';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import Movements from './components/Movements';
import Documents from './components/Documents';
import FiscalChat from './components/FiscalChat';
import Login from './components/Login';
import Simulator from './components/Simulator';
import Education from './components/Education';
import ManagerDashboard from './components/ManagerDashboard';
import Profile from './components/Profile';
import Onboarding from './components/Onboarding';
import Settings from './components/Settings';
import Calendar from './components/Calendar';
import Logo from './components/Logo';
import Toast from './components/Toast';
import IntroAnimation from './components/IntroAnimation';
import { PayrollDashboard } from './modules/payroll/components/PayrollDashboard';
import { DeliveryDashboard } from './modules/delivery/components/DeliveryDashboard';
import { IntegrationCatalog } from './modules/integrations/components/IntegrationCatalog';
import { CountryHub } from './modules/country-config/components/CountryHub';
import { PolicyManager } from './modules/policy-engine/components/PolicyManager'; 
import { AuditLogViewer } from './modules/core/audit/components/AuditLogViewer'; 
import { ApprovalInbox } from './modules/core/approvals/components/ApprovalInbox';
import { LayoutDashboard, Activity, MessageSquare, User, Menu } from 'lucide-react';

const MainLayout: React.FC = () => {
  const { currentUser, hasOnboarded, completeOnboarding } = useData();
  const [currentView, setView] = useState('dashboard');
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  // Redirect manager to their dashboard by default
  React.useEffect(() => {
    if (currentUser?.role === 'MANAGER' && currentView === 'dashboard') {
      setView('manager-dashboard');
    }
  }, [currentUser, currentView]);

  if (!currentUser) return <Login />;

  if (currentUser.role === 'RIDER' && !hasOnboarded) {
    return <Onboarding onFinish={completeOnboarding} />;
  }

  const renderView = () => {
    switch (currentView) {
      case 'dashboard': return <Dashboard setView={setView} />;
      case 'movements': return <Movements />;
      case 'calendar': return <Calendar />;
      case 'documents': return <Documents />;
      case 'chat': 
      case 'ai': return <FiscalChat />;
      case 'simulator': return <Simulator />;
      case 'education': return <Education setView={setView} />;
      case 'profile': return <Profile />;
      case 'settings': return <Settings setView={setView} />;

      // Enterprise / Manager Modules
      case 'manager-dashboard': return <ManagerDashboard />;
      case 'payroll': return <PayrollDashboard />;
      case 'delivery': return <DeliveryDashboard />;
      case 'integrations': return <IntegrationCatalog />;
      case 'countries': return <CountryHub />;
      case 'policies': return <PolicyManager />;
      case 'approvals': return <ApprovalInbox />; 
      case 'audit': return <AuditLogViewer />;

      default: return <Dashboard setView={setView} />;
    }
  };

  const navItems = [
    { id: 'dashboard', label: 'Inicio', icon: LayoutDashboard },
    { id: 'movements', label: 'Movs', icon: Activity },
    { id: 'ai', label: 'IA', icon: MessageSquare },
    { id: 'profile', label: 'Perfil', icon: User },
  ];

  return (
    <div className="flex h-screen bg-[#F8FAFC] font-sans text-slate-900 overflow-hidden">
      <Toast />

      {/* Sidebar - Fixed on desktop, hidden on mobile */}
      <Sidebar 
        currentView={currentView} 
        setView={setView} 
        isMobileMenuOpen={isMobileMenuOpen}
        setIsMobileMenuOpen={setIsMobileMenuOpen}
      />

      {/* Main Content Area */}
      <main className="flex-1 flex flex-col h-full relative overflow-hidden bg-[#F8FAFC]">

        {/* Mobile Header */}
        <header className="lg:hidden bg-white border-b border-slate-200 px-4 py-3 flex items-center justify-between z-20 shrink-0 shadow-sm">
          <Logo size="sm" />
          <button 
            onClick={() => setIsMobileMenuOpen(true)}
            className="p-2 text-slate-600 hover:bg-slate-100 rounded-lg transition-colors"
          >
            <Menu size={24} />
          </button>
        </header>

        {/* Scrollable Content View */}
        <div className="flex-1 overflow-y-auto p-4 md:p-8 scroll-smooth custom-scrollbar">
          <div className="max-w-7xl mx-auto min-h-full">
            {renderView()}
          </div>
        </div>

        {/* Mobile Bottom Nav */}
        <nav className="lg:hidden bg-white border-t border-slate-200 px-6 py-3 flex justify-between items-center z-30 safe-area-bottom shrink-0 shadow-[0_-4px_6px_-1px_rgba(0,0,0,0.05)]">
          {navItems.map((item) => (
            <button
              key={item.id}
              onClick={() => setView(item.id)}
              className={`flex flex-col items-center gap-1 transition-colors ${
                currentView === item.id ? 'text-blue-600' : 'text-slate-400 hover:text-slate-600'
              }`}
            >
              <item.icon size={24} strokeWidth={currentView === item.id ? 2.5 : 2} />
              <span className="text-[10px] font-bold">{item.label}</span>
            </button>
          ))}
        </nav>
      </main>
    </div>
  );
};

const App: React.FC = () => {
  const [showIntro, setShowIntro] = useState(true);

  return (
    <OrganizationProvider>
      <CountryProvider>
        <DataProvider>
          {showIntro ? (
            <IntroAnimation onComplete={() => setShowIntro(false)} />
          ) : (
            <MainLayout />
          )}
        </DataProvider>
      </CountryProvider>
    </OrganizationProvider>
  );
};

export default App;

