import React from 'react';
import { LayoutDashboard, Receipt, MessageSquare, GraduationCap, Settings, LogOut, Users, FileText, Activity, Eye, EyeOff, Calculator, Zap, AlertTriangle, Wrench, Building, Navigation, Globe, X, Package, Plug, DollarSign, Shield, CheckCircle, BarChart3, HelpCircle } from 'lucide-react';
import { useData } from '../contexts/DataContext';
import { UserRole } from '../types';
import Logo from './Logo';

interface SidebarProps {
  currentView: string;
  setView: (view: string) => void;
  isMobileMenuOpen: boolean;
  setIsMobileMenuOpen: (open: boolean) => void;
}

const Sidebar: React.FC<SidebarProps> = ({ currentView, setView, isMobileMenuOpen, setIsMobileMenuOpen }) => {
  const { currentUser, logout, privacyMode, togglePrivacyMode } = useData();

  const menuItems = currentUser?.role === UserRole.MANAGER || currentUser?.role === UserRole.ADMIN
  ? [
      { section: 'Gestión' },
      { id: 'manager-dashboard', label: 'Panel Clientes', icon: Users },
      { id: 'approvals', label: 'Aprobaciones', icon: CheckCircle },
      { section: 'Operaciones' },
      { id: 'payroll', label: 'Payroll Suite', icon: DollarSign },
      { id: 'delivery', label: 'Delivery Ops', icon: Package },
      { id: 'audit', label: 'Auditoría', icon: FileText },
      { section: 'Configuración' },
      { id: 'policies', label: 'Políticas', icon: Shield }, 
      { id: 'countries', label: 'Países', icon: Globe },
      { id: 'settings', label: 'Sistema', icon: Settings },
    ]
  : [
      { section: 'Principal' },
      { id: 'dashboard', label: 'Dashboard', icon: LayoutDashboard },
      { id: 'movements', label: 'Movimientos', icon: Activity },
      { id: 'documents', label: 'Documentos', icon: FileText },
      { section: 'Herramientas' },
      { id: 'delivery', label: 'Delivery', icon: Package },
      { id: 'simulator', label: 'Simulador', icon: Calculator },
      { id: 'integrations', label: 'Conexiones', icon: Plug },
      { section: 'Soporte' },
      { id: 'education', label: 'Academia', icon: GraduationCap },
      { id: 'ai', label: 'Asistente IA', icon: MessageSquare },
      { id: 'settings', label: 'Ajustes', icon: Settings },
    ];

  const handleNavClick = (viewId: string) => {
    setView(viewId);
    setIsMobileMenuOpen(false);
  };

  return (
    <>
      {/* Mobile Overlay */}
      <div 
        className={`fixed inset-0 bg-slate-900/80 backdrop-blur-sm z-40 lg:hidden transition-opacity duration-300 ${isMobileMenuOpen ? 'opacity-100' : 'opacity-0 pointer-events-none'}`}
        onClick={() => setIsMobileMenuOpen(false)}
      />

      <aside className={`
        fixed lg:static inset-y-0 left-0 z-50 w-72 bg-[#0F172A] text-slate-300 transform transition-transform duration-300 ease-in-out lg:translate-x-0 
        ${isMobileMenuOpen ? 'translate-x-0 shadow-2xl' : '-translate-x-full'}
        flex flex-col border-r border-slate-800
      `}>
        {/* Header */}
        <div className="h-20 flex items-center px-6 border-b border-slate-800">
          <Logo size="md" variant="dark" />
          <button onClick={() => setIsMobileMenuOpen(false)} className="lg:hidden ml-auto p-2 text-slate-400 hover:text-white transition-colors">
             <X size={20} />
          </button>
        </div>

        {/* Navigation */}
        <nav className="flex-1 overflow-y-auto py-6 px-4 space-y-1 custom-scrollbar">
          {menuItems.map((item, idx) => {
            if (item.section) {
              return (
                <div key={`sec-${idx}`} className="px-3 mt-6 mb-2">
                  <span className="text-[10px] font-bold uppercase tracking-wider text-slate-500 font-heading">{item.section}</span>
                </div>
              );
            }

            const isActive = currentView === item.id;
            return (
              <button
                key={item.id}
                onClick={() => item.id && handleNavClick(item.id)}
                className={`w-full flex items-center gap-3 px-3 py-3 rounded-xl text-sm font-medium transition-all duration-200 group relative ${
                  isActive 
                    ? 'bg-[#2563EB] text-white shadow-lg shadow-blue-900/40' 
                    : 'text-slate-400 hover:text-white hover:bg-slate-800'
                }`}
              >
                {item.icon && <item.icon size={18} className={`transition-colors ${isActive ? 'text-white' : 'text-slate-500 group-hover:text-slate-300'}`} />}
                <span>{item.label}</span>
                {isActive && (
                  <div className="absolute right-3 w-1.5 h-1.5 bg-white rounded-full animate-pulse shadow-[0_0_8px_rgba(255,255,255,0.8)]"></div>
                )}
              </button>
            );
          })}
        </nav>

        {/* Footer Actions */}
        <div className="p-4 border-t border-slate-800 bg-[#0B1120]">
          {/* Privacy Mode */}
          <button 
            onClick={togglePrivacyMode}
            className="w-full flex items-center justify-between px-4 py-3 rounded-xl bg-slate-800/50 hover:bg-slate-800 text-xs font-medium text-slate-300 transition-colors border border-slate-700 mb-4 group"
          >
            <span className="flex items-center gap-2">
              {privacyMode ? <EyeOff size={14} className="text-slate-400 group-hover:text-white transition-colors" /> : <Eye size={14} className="text-slate-400 group-hover:text-white transition-colors" />}
              {privacyMode ? 'Modo Privado' : 'Mostrar Saldos'}
            </span>
            <div className={`w-8 h-4 rounded-full relative transition-colors ${privacyMode ? 'bg-[#22C55E]' : 'bg-slate-600'}`}>
               <div className={`absolute top-0.5 w-3 h-3 bg-white rounded-full transition-transform shadow-sm ${privacyMode ? 'left-4.5' : 'left-0.5'}`}></div>
            </div>
          </button>

          {/* User Profile Snippet */}
          <div className="flex items-center gap-3 px-1">
            <div className="w-10 h-10 rounded-xl bg-gradient-to-br from-blue-600 to-indigo-700 flex items-center justify-center text-white font-bold shadow-lg border border-slate-700">
              {currentUser?.name.charAt(0).toUpperCase()}
            </div>
            <div className="flex-1 min-w-0">
              <p className="text-sm font-semibold text-white truncate">{currentUser?.name}</p>
              <p className="text-[10px] text-slate-500 font-bold uppercase tracking-wider">{currentUser?.role}</p>
            </div>
            <button 
              onClick={logout}
              className="p-2 text-slate-500 hover:text-red-400 hover:bg-red-500/10 rounded-xl transition-colors"
              title="Cerrar Sesión"
            >
              <LogOut size={18} />
            </button>
          </div>
        </div>
      </aside>
    </>
  );
};

