import React, { useState } from 'react';
import { Package, Car, Building2, CreditCard, FileText, Briefcase, Zap } from 'lucide-react';

interface LogoResolverProps {
  id: string;
  name: string;
  domain?: string;
  category?: string;
  className?: string;
  size?: 'sm' | 'md' | 'lg' | 'xl';
}

const LogoResolver: React.FC<LogoResolverProps> = ({ 
  id, 
  name, 
  domain, 
  category = 'other', 
  className = '', 
  size = 'md' 
}) => {
  const [errorLevel, setErrorLevel] = useState(0); // 0: Try Local, 1: Try Remote, 2: Show Placeholder

  const handleLocalError = () => {
    // If local file fails, try fetching from Clearbit using domain or name
    if (domain) {
      setErrorLevel(1);
    } else {
      setErrorLevel(2);
    }
  };

  const handleRemoteError = () => {
    // If remote fails, show placeholder
    setErrorLevel(2);
  };

  // Dimensions based on size
  const sizeClasses = {
    sm: 'w-8 h-8 p-1',
    md: 'w-12 h-12 p-2',
    lg: 'w-16 h-16 p-3',
    xl: 'w-24 h-24 p-4'
  };

  const currentSizeClass = sizeClasses[size] || sizeClasses.md;

  // Render Logic

  // 1. Try Local File (/brands/{id}.svg)
  if (errorLevel === 0) {
    return (
      <div className={`bg-white rounded-xl border border-slate-100 flex items-center justify-center overflow-hidden ${currentSizeClass} ${className}`}>
        <img 
          src={`/brands/${id}.svg`} 
          alt={name} 
          className="w-full h-full object-contain"
          onError={handleLocalError}
        />
      </div>
    );
  }

  // 2. Try Remote (Clearbit)
  if (errorLevel === 1 && domain) {
    return (
      <div className={`bg-white rounded-xl border border-slate-100 flex items-center justify-center overflow-hidden ${currentSizeClass} ${className}`}>
        <img 
          src={`https://logo.clearbit.com/${domain}`} 
          alt={name} 
          className="w-full h-full object-contain"
          onError={handleRemoteError}
        />
      </div>
    );
  }

  // 3. Premium Placeholder (Fallback)
  // Deterministic color generation based on name string
  const getGradient = (str: string) => {
    const hash = str.split('').reduce((acc, char) => char.charCodeAt(0) + acc, 0);
    const hues = [
      'from-blue-500 to-cyan-400',
      'from-purple-500 to-pink-400', 
      'from-green-500 to-emerald-400',
      'from-orange-500 to-amber-400',
      'from-rose-500 to-red-400',
      'from-indigo-500 to-blue-400'
    ];
    return hues[hash % hues.length];
  };

  const getIcon = () => {
    switch (category) {
      case 'delivery': return <Package size={24} className="text-white opacity-90" />;
      case 'mobility': return <Car size={24} className="text-white opacity-90" />;
      case 'banking': return <Building2 size={24} className="text-white opacity-90" />;
      case 'payments': return <CreditCard size={24} className="text-white opacity-90" />;
      case 'accounting': return <FileText size={24} className="text-white opacity-90" />;
      default: return <Briefcase size={24} className="text-white opacity-90" />;
    }
  };

  const initials = name.substring(0, 2).toUpperCase();

  return (
    <div className={`rounded-xl shadow-sm flex items-center justify-center relative overflow-hidden bg-gradient-to-br ${getGradient(name)} ${currentSizeClass} ${className}`}>
      {/* Background Pattern */}
      <div className="absolute inset-0 opacity-20">
         <Zap className="w-full h-full text-black rotate-12 scale-150 translate-x-2" />
      </div>

      {/* Content */}
      <div className="relative z-10 flex flex-col items-center justify-center">
         {size === 'lg' || size === 'xl' ? (
           <>
             {getIcon()}
             {size === 'xl' && <span className="text-[10px] font-bold text-white mt-1 tracking-widest">{initials}</span>}
           </>
         ) : (
           <span className="text-white font-bold text-sm tracking-wider">{initials}</span>
         )}
      </div>
    </div>
  );
};

export default LogoResolver;

import { useMemo } from 'react';
import { GLOBAL_INTEGRATION_CATALOG } from '../data/catalog';
import { IntegrationDef, IntegrationCategory } from '../../../types';

interface UseIntegrationsProps {
  countryCode?: string;
  category?: IntegrationCategory | 'all';
  limit?: number;
}

export const useIntegrations = ({ countryCode, category = 'all', limit }: UseIntegrationsProps = {}) => {

  const integrations = useMemo(() => {
    let result = GLOBAL_INTEGRATION_CATALOG.filter(item => item.status !== 'deprecated');

    // 1. Filter by Country
    if (countryCode) {
      result = result.filter(item => 
        item.supported_countries.length === 0 || // Global
        item.supported_countries.includes(countryCode)
      );
    }

    // 2. Filter by Category
    if (category !== 'all') {
      result = result.filter(item => item.category === category);
    }

    // 3. Sort by Ranking (Descending)
    result.sort((a, b) => b.ranking - a.ranking);

    // 4. Limit
    if (limit) {
      result = result.slice(0, limit);
    }

    return result;
  }, [countryCode, category, limit]);

  const getByCategory = (cat: IntegrationCategory) => {
    return integrations.filter(i => i.category === cat);
  };

  return {
    integrations,
    getByCategory,
    total: integrations.length
  };
};

