                   <div className="flex justify-between items-start mb-4">
                      <LogoResolver 
                        id={int.id} 
                        name={int.name} 
                        domain={int.domain} 
                        category={int.category} 
                        size="lg"
                      />

                      {int.ranking > 95 && (
                        <span className="px-2 py-1 bg-yellow-50 text-yellow-700 text-[10px] font-bold uppercase tracking-wider rounded-lg border border-yellow-100 flex items-center gap-1">
                          Top
                        </span>
                      )}
                   </div>

                   <h3 className="font-bold text-lg text-slate-900 mb-1">{int.name}</h3>
                   <div className="flex flex-wrap gap-2 mb-3">
                      <span className="text-xs text-slate-500 bg-slate-50 px-2 py-0.5 rounded border border-slate-100 capitalize">
                        {int.category}
                      </span>
                      {int.supported_countries.length === 0 ? (
                        <span className="text-xs text-blue-600 bg-blue-50 px-2 py-0.5 rounded border border-blue-100 flex items-center gap-1">
                          <Globe size={10} /> Global
                        </span>
                      ) : (
                        <span className="text-xs text-slate-400 px-1 py-0.5">
                          {int.supported_countries.join(', ')}
                        </span>
                      )}
                   </div>

                   <p className="text-xs text-slate-500 line-clamp-2 min-h-[2.5em]">
                     {int.description || `Integración oficial con ${int.name} para sincronización de datos.`}
                   </p>
                 </div>

                 <div className="mt-5 pt-4 border-t border-slate-50">
                    {isInstalled(int.id) ? (
                       <button className="w-full py-2.5 bg-emerald-50 text-emerald-700 border border-emerald-100 rounded-xl text-xs font-bold flex items-center justify-center gap-2 cursor-default">
                          <Check size={16} /> Activa
                       </button>
                    ) : (
                       <button className="w-full py-2.5 bg-slate-900 text-white rounded-xl text-xs font-bold flex items-center justify-center gap-2 hover:bg-blue-600 transition-colors shadow-lg shadow-slate-200 group-hover:shadow-blue-500/20">
                          <Plus size={16} /> Conectar
                       </button>
                    )}
                 </div>
              </div>
           ))}
        </div>
      ) : (
        <div className="text-center py-20 bg-slate-50 rounded-3xl border-2 border-dashed border-slate-200">
           <div className="w-16 h-16 bg-white rounded-full flex items-center justify-center mx-auto mb-4 text-slate-300 shadow-sm">
             <Search size={32} />
           </div>
           <h3 className="text-lg font-bold text-slate-700">No se encontraron resultados</h3>
           <p className="text-slate-500 text-sm mt-1">Prueba con otra categoría o término de búsqueda.</p>
           <button 
             onClick={() => { setSearchTerm(''); setSelectedCat('all'); }}
             className="mt-4 text-blue-600 font-bold text-sm hover:underline"
           >
             Limpiar filtros
           </button>
        </div>
      )}
    </div>
  );
};

import React from 'react';
import { Sparkles } from 'lucide-react';

interface LogoProps {
  size?: 'sm' | 'md' | 'lg' | 'xl';
  showText?: boolean;
  className?: string;
  variant?: 'dark' | 'light';
  animated?: boolean;
}

const Logo: React.FC<LogoProps> = ({ 
  size = 'md', 
  showText = true, 
  className = '', 
  variant = 'light',
  animated = false
}) => {
  const sizeConfig = {
    sm: { icon: 16, container: 'w-8 h-8', text: 'text-lg' },
    md: { icon: 20, container: 'w-10 h-10', text: 'text-xl' },
    lg: { icon: 32, container: 'w-16 h-16', text: 'text-3xl' },
    xl: { icon: 48, container: 'w-24 h-24', text: 'text-5xl' }
  };

  const config = sizeConfig[size];
  const textColor = variant === 'dark' ? 'text-white' : 'text-slate-900';

  return (
    <div className={`flex items-center gap-3 ${className}`}>
      <div 
        className={`
          ${config.container} bg-gradient-to-br from-blue-600 to-indigo-600 rounded-xl flex items-center justify-center text-white shadow-lg shadow-blue-500/20
          ${animated ? 'animate-[bounce_3s_infinite]' : ''}
        `}
      >
        <Sparkles 
          size={config.icon} 
          fill="currentColor" 
          className={animated ? 'animate-[spin_4s_linear_infinite]' : ''} 
        />
      </div>

      {showText && (
        <span className={`font-black tracking-tight ${config.text} ${textColor}`}>
          Labora<span className="text-emerald-500">+</span>
        </span>
      )}
    </div>
  );
};

export default Logo;

import React, { useState, useMemo } from 'react';
import { useCountry } from '../../../contexts/CountryContext';
import { useData } from '../../../contexts/DataContext';
import { IntegrationCategory, IntegrationDef } from '../../../types';
import { useIntegrations } from '../hooks/useIntegrations';
import LogoResolver from '../../../components/LogoResolver';
import { Plug, Check, Plus, Search, Filter, Globe, Package, Car, Building2, CreditCard, FileText, Settings, ExternalLink, Loader2 } from 'lucide-react';

export const IntegrationCatalog: React.FC = () => {
  const { selectedCountry, countries, selectCountry } = useCountry();
  const { currentUser, showNotification, updateUserConfig } = useData();

  const [searchTerm, setSearchTerm] = useState('');
  const [selectedCat, setSelectedCat] = useState<IntegrationCategory | 'all'>('all');
  const [installingId, setInstallingId] = useState<string | null>(null);

  // Custom hook brings data sorted by ranking and filtered by country
  const { integrations } = useIntegrations({
    countryCode: selectedCountry.country_code,
    category: selectedCat
  });

  const categories: { id: IntegrationCategory | 'all', label: string, icon: any }[] = [
    { id: 'all', label: 'Todas', icon: Filter },
    { id: 'delivery', label: 'Delivery', icon: Package },
    { id: 'mobility', label: 'Movilidad', icon: Car },
    { id: 'banking', label: 'Bancos', icon: Building2 },
    { id: 'payments', label: 'Pagos', icon: CreditCard },
    { id: 'accounting', label: 'Contabilidad', icon: FileText },
  ];

  // Client-side search filtering
  const filtered = useMemo(() => {
    return integrations.filter(i => 
      i.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      i.category.toLowerCase().includes(searchTerm.toLowerCase())
    );
  }, [integrations, searchTerm]);

  // Check if integration is already active for the current user
  const isInstalled = (integration: IntegrationDef) => {
    if (!currentUser) return false;

    // Normalize checking against user arrays
    const userPlatforms = (currentUser.platforms || []).map(p => p.toLowerCase());
    const userBanks = (currentUser.banks || []).map(b => b.toLowerCase());

    // Check by ID or Name (handling different naming conventions)
    const idMatch = userPlatforms.includes(integration.id.toLowerCase()) || userBanks.includes(integration.id.toLowerCase());
    const nameMatch = userPlatforms.includes(integration.name.toLowerCase()) || userBanks.includes(integration.name.toLowerCase());

    // Special check for mock data consistency
    if (integration.id === 'uber' && userPlatforms.includes('uber eats')) return true;

    return idMatch || nameMatch;
  };

  const handleInstall = async (integration: IntegrationDef) => {
    if (!currentUser) return;
    setInstallingId(integration.id);

    // Simulate API delay
    await new Promise(resolve => setTimeout(resolve, 1500));

    try {
      let newPlatforms = [...currentUser.platforms];
      let newBanks = [...(currentUser.banks || [])];

      if (['delivery', 'mobility'].includes(integration.category)) {
        newPlatforms.push(integration.name);
      } else if (integration.category === 'banking') {
        newBanks.push(integration.name);
      } else {
        // Fallback for other categories
        newPlatforms.push(integration.name);
      }

      updateUserConfig(newPlatforms, newBanks);
      showNotification('success', `Se ha conectado ${integration.name} correctamente.`);
    } catch (error) {
      showNotification('error', 'Error al conectar la integración.');
    } finally {
      setInstallingId(null);
    }
  };

  const handleConfigure = (integration: IntegrationDef) => {
    showNotification('info', `Abriendo configuración de ${integration.name}...`);
    // Logic to open specific settings modal would go here
  };

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4">

      {/* Header & Controls */}
      <div className="bg-white p-6 rounded-[24px] border border-slate-200 shadow-sm">
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6 mb-6">
          <div>
            <h2 className="text-2xl font-bold text-slate-900 flex items-center gap-2">
              <Plug className="text-blue-600" size={24} /> Marketplace Global
            </h2>
            <p className="text-slate-500 mt-1 text-sm">
              Explora {integrations.length} integraciones disponibles para <span className="font-bold text-slate-800">{selectedCountry.display_name}</span>.
            </p>
          </div>

          <div className="flex flex-col sm:flex-row gap-3 w-full md:w-auto">
             <div className="relative group flex-1 md:w-64">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-blue-500 transition-colors" size={18} />
                <input 
                  type="text" 
                  placeholder="Buscar app, banco..."
                  value={searchTerm}
                  onChange={e => setSearchTerm(e.target.value)}
                  className="pl-10 pr-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm focus:ring-2 focus:ring-blue-500 focus:bg-white outline-none w-full transition-all"
                />
             </div>

             {/* Country Quick Switcher */}
             <select 
               value={selectedCountry.country_code}
               onChange={(e) => selectCountry(e.target.value)}
               className="p-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm font-bold text-slate-700 outline-none focus:ring-2 focus:ring-blue-500 cursor-pointer"
             >
               {countries.map(c => (
                 <option key={c.country_code} value={c.country_code}>{c.country_code} - {c.display_name}</option>
               ))}
             </select>
          </div>
        </div>

        {/* Categories Tabs */}
        <div className="flex gap-2 overflow-x-auto pb-2 scrollbar-hide">
          {categories.map(cat => (
            <button
              key={cat.id}
              onClick={() => setSelectedCat(cat.id)}
              className={`flex items-center gap-2 px-4 py-2 rounded-xl text-sm font-bold transition-all whitespace-nowrap ${
                selectedCat === cat.id 
                  ? 'bg-slate-900 text-white shadow-lg' 
                  : 'bg-white border border-slate-200 text-slate-600 hover:bg-slate-50'
              }`}
            >
              <cat.icon size={16} />
              {cat.label}
            </button>
          ))}
        </div>
      </div>

      {/* Grid */}
      {filtered.length > 0 ? (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
           {filtered.map(int => {
              const installed = isInstalled(int);
              const isInstalling = installingId === int.id;

              return (
                <div key={int.id} className={`bg-white p-5 rounded-[24px] border transition-all hover:-translate-y-1 group flex flex-col justify-between h-full ${installed ? 'border-green-200 shadow-sm' : 'border-slate-200 shadow-sm hover:shadow-md'}`}>

                   <div>
                     <div className="flex justify-between items-start mb-4">
                        <LogoResolver 
                          id={int.id} 
                          name={int.name} 
                          domain={int.domain} 
                          category={int.category} 
                          size="lg"
                          className="shadow-sm"
                        />

                        {int.ranking > 95 && !installed && (
                          <span className="px-2 py-1 bg-yellow-50 text-yellow-700 text-[10px] font-bold uppercase tracking-wider rounded-lg border border-yellow-100 flex items-center gap-1">
                            Popular
                          </span>
                        )}
                        {installed && (
                          <div className="w-6 h-6 bg-green-100 text-green-600 rounded-full flex items-center justify-center">
                            <Check size={14} strokeWidth={3} />
                          </div>
                        )}
                     </div>

                     <h3 className="font-bold text-lg text-slate-900 mb-1 leading-tight">{int.name}</h3>

                     <div className="flex flex-wrap gap-2 mb-3">
                        <span className="text-[10px] font-bold uppercase tracking-wider text-slate-500 bg-slate-50 px-2 py-1 rounded-lg border border-slate-100">
                          {int.category}
                        </span>
                        {int.supported_countries.length === 0 ? (
                          <span className="text-[10px] font-bold text-blue-600 bg-blue-50 px-2 py-1 rounded-lg border border-blue-100 flex items-center gap-1">
                            <Globe size={10} /> Global
                          </span>
                        ) : (
                          <span className="text-[10px] font-bold text-slate-400 px-1 py-1">
                            {int.supported_countries.length > 3 ? `${int.supported_countries.slice(0,3).join(', ')}...` : int.supported_countries.join(', ')}
                          </span>
                        )}
                     </div>

                     <p className="text-xs text-slate-500 line-clamp-2 min-h-[2.5em] leading-relaxed">
                       {int.description || `Integración oficial con ${int.name} para sincronización de datos automática y conciliación.`}
                     </p>
                   </div>

                   <div className="mt-5 pt-4 border-t border-slate-50">
                      {installed ? (
                         <div className="flex gap-2">
                           <button 
                             className="flex-1 py-2.5 bg-green-50 text-green-700 border border-green-100 rounded-xl text-xs font-bold flex items-center justify-center gap-2 cursor-default"
                           >
                              Conectado
                           </button>
                           <button 
                             onClick={() => handleConfigure(int)}
                             className="w-10 flex items-center justify-center bg-white border border-slate-200 rounded-xl text-slate-400 hover:text-slate-600 hover:bg-slate-50 transition-colors"
                             title="Configurar"
                           >
                             <Settings size={16} />
                           </button>
                         </div>
                      ) : (
                         <button 
                           onClick={() => handleInstall(int)}
                           disabled={isInstalling}
                           className="w-full py-2.5 bg-slate-900 text-white rounded-xl text-xs font-bold flex items-center justify-center gap-2 hover:bg-blue-600 transition-all shadow-lg shadow-slate-200 group-hover:shadow-blue-500/20 active:scale-95 disabled:opacity-70 disabled:cursor-not-allowed"
                         >
                            {isInstalling ? (
                              <Loader2 size={16} className="animate-spin" />
                            ) : (
                              <>
                                <Plus size={16} /> Conectar
                              </>
                            )}
                         </button>
                      )}
                   </div>
                </div>
              );
           })}
        </div>
      ) : (
        <div className="text-center py-20 bg-slate-50 rounded-[32px] border-2 border-dashed border-slate-200">
           <div className="w-16 h-16 bg-white rounded-full flex items-center justify-center mx-auto mb-4 text-slate-300 shadow-sm">
             <Search size={32} />
           </div>
           <h3 className="text-lg font-bold text-slate-700">No se encontraron resultados</h3>
           <p className="text-slate-500 text-sm mt-1">Prueba con otra categoría o término de búsqueda.</p>
           <button 
             onClick={() => { setSearchTerm(''); setSelectedCat('all'); }}
             className="mt-4 text-blue-600 font-bold text-sm hover:underline"
           >
             Limpiar filtros
           </button>
        </div>
      )}
    </div>
  );
};

export enum UserRole {
  RIDER = 'RIDER',
  MANAGER = 'MANAGER',
  ADMIN = 'ADMIN'
}

export interface NotificationSettings {
  email: boolean;
  push: boolean;
  whatsapp: boolean;
  lowIncomeAlert: boolean;
  paymentAlert: boolean;
}

export interface Organization {
  id: string;
  name: string;
  plan: 'starter' | 'growth' | 'enterprise';
  country_code: string;
  feature_flags: Record<string, boolean>;
}

export interface User {
  id: string;
  name: string;
  email: string;
  phone?: string;
  address?: string;
  photoUrl?: string;
  role: UserRole;
  organizationId?: string; // Multi-tenant link
  platforms: string[]; // e.g., 'Uber', 'Glovo'
  banks?: string[]; // e.g., 'BBVA', 'Revolut'
  managerId?: string; // If linked to a manager
  currencyPreference?: string;
  notificationSettings?: NotificationSettings;
}

// --- INTEGRATION ENGINE TYPES ---

export type IntegrationCategory = 'delivery' | 'mobility' | 'banking' | 'payments' | 'accounting' | 'hr';

export interface IntegrationDef {
  id: string;
  name: string;
  category: IntegrationCategory;
  domain: string; // Used for logo fetching (e.g., uber.com)
  supported_countries: string[]; // ['ES', 'MX', 'US'] or [] for global
  status: 'active' | 'beta' | 'deprecated';
  ranking: number; // 1-100, higher is better/more popular
  description?: string;
  is_installed?: boolean; // Runtime state
}

// --- POLICY ENGINE TYPES ---
export interface PolicyRule {
  id: string;
  field: string; // e.g., 'payroll.total_cost'
  operator: 'gt' | 'lt' | 'eq' | 'neq' | 'contains';
  value: any;
}

export interface PolicyAction {
  type: 'block' | 'require_approval' | 'notify' | 'log';
  message?: string;
  target_role?: UserRole;
}

export interface Policy {
  id: string;
  organizationId: string;
  name: string;
  description: string;
  enabled: boolean;
  priority: number; // 1-100 (Higher runs first)
  scope: {
    country_code?: string; // Apply only to specific country
    module?: string; // 'payroll', 'delivery', etc.
  };
  rules: PolicyRule[];
  actions: PolicyAction[];
}

export type ApprovalStatus = 'pending' | 'approved' | 'rejected';

export interface ApprovalRequest {
  id: string;
  organizationId: string;
  requesterId: string;
  requesterName: string;
  entityType: 'payroll_run' | 'refund' | 'expense' | 'variable_change';
  entityId?: string; // Optional ID if the entity exists in draft state
  status: ApprovalStatus;
  payload: any; // Snapshot of the data needing approval (e.g. { total_cost: 15000 })
  policyTriggered?: string; // Name of the policy that caused this
  createdAt: string;
  resolvedAt?: string;
  resolvedBy?: string;
}

// --- EXISTING TYPES ---

export interface Employee {
  id: string;
  name: string;
  role: string;
  country_code: string;
  base_salary: number;
  currency: string;
  status: 'active' | 'onboarding' | 'terminated';
  national_id?: string; // DNI, SSN, CURP
  bank_account?: string; // IBAN, Routing
  start_date: string;
}

export interface PayrollRun {
  id: string;
  period: string; // "2024-04"
  status: 'draft' | 'approved' | 'paid' | 'needs_approval' | 'rejected';
  total_cost: number;
  employee_count: number;
  currency: string;
  date_processed: string;
}

export interface Payslip {
  id: string;
  employee_id: string;
  period: string;
  gross_pay: number;
  net_pay: number;
  deductions: {
    name: string;
    amount: number;
    rate?: number;
  }[];
  employer_cost: number;
}

// Legacy Integration Type (Deprecated in favor of IntegrationDef)
export interface Integration {
  id: string;
  name: string;
  type: IntegrationCategory;
  logo_url: string;
  status: 'active' | 'inactive' | 'pending';
  country_codes: string[]; // Supported countries
  is_installed: boolean;
}

export interface DeliveryOrder {
  id: string;
  platform: string;
  status: 'pending' | 'picking_up' | 'delivering' | 'delivered' | 'cancelled';
  customer_name: string;
  address: string;
  earnings: number;
  distance_km: number;
  timestamp: string;
  issues?: string[];
}

export interface Vehicle {
  type: 'moto' | 'bici' | 'coche' | 'patinete';
  model: string;
  plate?: string;
  lastMaintenanceDate: string;
  lastMaintenanceKm: number;
  currentKm: number;
  nextMaintenanceKm: number;
}

export interface MaintenanceRecord {
  id: string;
  date: string;
  cost: number;
  km: number;
  description: string;
  type: 'preventive' | 'repair' | 'tires' | 'other';
  nextPlannedKm?: number;
}

export interface Income {
  id: string;
  userId: string;
  platform: string;
  date: string; // ISO Date
  amount: number;
  retention: number; // IRPF retention if applicable
}

export enum ExpenseCategory {
  GASOLINA = 'Gasolina',
  MANTENIMIENTO = 'Mantenimiento',
  COMIDA = 'Comida',
  MOVIL = 'Móvil',
  CUOTA_AUTONOMO = 'Cuota Autónomo',
  EQUIPAMIENTO = 'Equipamiento',
  MARKETING = 'Marketing',
  SOFTWARE = 'Suscripciones Software',
  FORMACION = 'Formación',
  PEAJES = 'Peajes',
  IMPUESTOS = 'Impuestos No Reembolsables',
  SEGUROS = 'Seguros',
  OTROS = 'Otros'
}

export interface Expense {
  id: string;
  userId: string;
  category: ExpenseCategory | string;
  date: string;
  amount: number;
  receiptUrl?: string; // Base64 or URL
  notes?: string;
  isRecurring?: boolean;
}

export interface Document {
  id: string;
  userId: string;
  type: 'Factura' | 'Trimestre' | 'Alta' | 'Otro';
  name: string;
  date: string;
  content?: string; // Base64
}

export interface FiscalSummary {
  totalIncome: number;
  totalExpenses: number;
  netProfit: number;
  estimatedIRPF: number;
  quarter: string; // e.g., "Q1 2024"
}

export interface ChatMessage {
  id: string;
  role: 'user' | 'model';
  text: string;
  timestamp: number;
}

export interface Payment {
  id: string;
  platform: string; // 'Uber', 'Glovo', etc.
  amount: number;
  date: string; // YYYY-MM-DD
  status: 'pending' | 'received';
  estimated: boolean;
  domain?: string; // for logo
}

export interface Notification {
  id: string;
  type: 'success' | 'error' | 'info';
  message: string;
}

