      if (p.includes('deliveroo')) return 'https://logo.clearbit.com/deliveroo.co.uk';
      if (p.includes('rappi')) return 'https://logo.clearbit.com/rappi.com';
      if (p.includes('bolt')) return 'https://logo.clearbit.com/bolt.eu';
      return null;
