              </div>
              <Loader2 className="animate-spin text-[#2D6CDF]" size={32} />
            </div>
          )}

          {/* STEP 4: SUCCESS */}
          {step === 'success' && (
            <div className="py-10 flex flex-col items-center text-center space-y-4 animate-in zoom-in">
