import React, { useState } from 'react';
import { useData } from '../../../contexts/DataContext';
import { Users, Search, Filter, MoreHorizontal, MessageSquare, Download, CheckCircle, AlertCircle } from 'lucide-react';

export const PeopleHub: React.FC = () => {
  const { currentUser, getUsersByManager, getFiscalSummary } = useData();
  const [filter, setFilter] = useState<'all' | 'risk' | 'safe'>('all');

  if (!currentUser) return null;

  // Logic extracted from old ManagerDashboard
  let clients = getUsersByManager(currentUser.id);
  if (filter === 'risk') clients = clients.filter(c => getFiscalSummary(c.id).netProfit < 0);

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4">
      <div className="flex justify-between items-end">
        <div>
          <h2 className="text-3xl font-bold text-[#1A1A1A] flex items-center gap-2">
            <Users className="text-[#2D6CDF]" /> People & Clients
          </h2>
          <p className="text-gray-500 mt-1">Gestión de {clients.length} usuarios asignados.</p>
        </div>
        <button className="bg-[#1A1A1A] text-white px-4 py-2 rounded-xl font-bold text-sm hover:bg-black transition-colors">
          + Nuevo Cliente
        </button>
      </div>

      {/* Search and Filter Bar */}
      <div className="bg-white p-4 rounded-2xl border border-gray-100 shadow-sm flex flex-col md:flex-row gap-4 items-center justify-between">
        <div className="relative w-full md:w-96">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
          <input 
            type="text" 
            placeholder="Buscar por nombre, DNI o email..." 
            className="w-full pl-10 pr-4 py-2.5 bg-gray-50 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-[#2D6CDF]"
          />
        </div>
        <div className="flex gap-2 w-full md:w-auto">
          <button 
            onClick={() => setFilter('all')}
            className={`px-4 py-2 rounded-xl text-sm font-bold transition-colors ${filter === 'all' ? 'bg-gray-900 text-white' : 'bg-gray-50 text-gray-600'}`}
          >
            Todos
          </button>
          <button 
            onClick={() => setFilter('risk')}
            className={`px-4 py-2 rounded-xl text-sm font-bold transition-colors ${filter === 'risk' ? 'bg-red-50 text-red-600' : 'bg-gray-50 text-gray-600'}`}
          >
            En Riesgo
          </button>
        </div>
      </div>

      {/* Clients Grid */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {clients.map(client => {
          const summary = getFiscalSummary(client.id);
          const status = summary.netProfit >= 0 ? 'ok' : 'warning'; 

          return (
            <div key={client.id} className="bg-white p-6 rounded-[24px] shadow-sm border border-gray-100 hover:shadow-md transition-all group">
              <div className="flex justify-between items-start mb-6">
                <div className="flex items-center gap-4">
                  <div className="w-14 h-14 rounded-full bg-gray-100 flex items-center justify-center text-xl font-bold text-gray-500">
                    {client.name.charAt(0)}
                  </div>
                  <div>
                    <h3 className="font-bold text-lg text-gray-900">{client.name}</h3>
                    <div className="flex items-center gap-2 mt-1">
                       {status === 'ok' ? (
                        <span className="inline-flex items-center gap-1 px-2 py-0.5 bg-green-100 text-green-700 rounded-full text-xs font-bold uppercase tracking-wider">
                          <CheckCircle size={10} /> Al día
                        </span>
                      ) : (
                        <span className="inline-flex items-center gap-1 px-2 py-0.5 bg-red-100 text-red-700 rounded-full text-xs font-bold uppercase tracking-wider">
                          <AlertCircle size={10} /> Riesgo
                        </span>
                      )}
                      <span className="text-xs text-gray-400">ID: {client.id}</span>
                    </div>
                  </div>
                </div>
                <button className="p-2 hover:bg-gray-50 rounded-lg text-gray-400">
                  <MoreHorizontal size={20} />
                </button>
              </div>

              <div className="grid grid-cols-3 gap-4 mb-6">
                <div className="p-3 bg-gray-50 rounded-xl">
                  <p className="text-xs text-gray-500 uppercase font-bold mb-1">Ingresos</p>
                  <p className="font-bold text-gray-900">{summary.totalIncome}€</p>
                </div>
                <div className="p-3 bg-gray-50 rounded-xl">
                  <p className="text-xs text-gray-500 uppercase font-bold mb-1">Gastos</p>
                  <p className="font-bold text-gray-900">{summary.totalExpenses}€</p>
                </div>
                <div className="p-3 bg-gray-50 rounded-xl">
                  <p className="text-xs text-gray-500 uppercase font-bold mb-1">Beneficio</p>
                  <p className={`font-bold ${summary.netProfit > 0 ? 'text-green-600' : 'text-red-600'}`}>{summary.netProfit}€</p>
                </div>
              </div>

              <div className="flex gap-3 border-t border-gray-100 pt-4">
                <button className="flex-1 flex items-center justify-center gap-2 py-2.5 rounded-xl bg-[#2D6CDF] text-white text-sm font-bold shadow-lg shadow-blue-500/20 hover:bg-blue-700 transition-colors">
                  <Download size={16} /> Informe
                </button>
                <button className="flex-1 flex items-center justify-center gap-2 py-2.5 rounded-xl bg-gray-50 text-gray-700 text-sm font-bold hover:bg-gray-100 transition-colors">
                  <MessageSquare size={16} /> Contactar
                </button>
              </div>
            </div>
          );
        })}

        {clients.length === 0 && (
           <div className="col-span-2 py-12 text-center text-gray-400 bg-white rounded-[24px] border border-dashed border-gray-200">
              No se encontraron clientes con este filtro.
           </div>
        )}
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { DataProvider, useData } from './contexts/DataContext';
