const MainLayout: React.FC = () => {
  const { currentUser, hasOnboarded, completeOnboarding } = useData();
  const [currentView, setView] = useState('dashboard');
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  // Redirect manager to their dashboard by default
  React.useEffect(() => {
    if (currentUser?.role === 'MANAGER' && currentView === 'dashboard') {
      // Keep 'dashboard' string but it renders ManagerDashboard component
    }
  }, [currentUser, currentView]);

  if (!currentUser) return <Login />;

  if (currentUser.role === 'RIDER' && !hasOnboarded) {
    return <Onboarding onFinish={completeOnboarding} />;
  }

  const renderView = () => {
    switch (currentView) {
      // --- CORE SECTIONS ---
      case 'dashboard': 
        return currentUser.role === 'MANAGER' || currentUser.role === 'ADMIN' 
          ? <ManagerDashboard /> 
          : <Dashboard setView={setView} />;

      case 'all-modules': return <ModulesCenter setView={setView} />;
      case 'people': return <PeopleHub />;
      case 'money': return <MoneyHub />;
      case 'operations': return <OperationsHub />;
      case 'integrations': return <IntegrationCatalog />;
      case 'automation': return <AutomationHub />;
      case 'settings': return <SettingsHub />;

      // --- LEGACY / DIRECT LINKS (Mapped to new Hubs or kept) ---
      // These act as shortcuts from ModulesCenter
      case 'manager-dashboard': return <ManagerDashboard />;
      case 'payroll': return <MoneyHub />; // Redirect to Hub (default tab)
      case 'banking': return <MoneyHub />; // In future, can pass prop to open specific tab
      case 'movements': return <MoneyHub />;
      case 'docs': return <MoneyHub />;

      case 'delivery': return <OperationsHub />; 
      case 'risks': return <OperationsHub />;
      case 'hot-zones': return <OperationsHub />;
      case 'routes': return <OperationsHub />;

      case 'policies': return <AutomationHub />;
      case 'approvals': return <AutomationHub />;
      case 'ai': return <AutomationHub />;

      case 'countries': return <SettingsHub />;
      case 'audit': return <SettingsHub />;

      case 'profile': return <Profile />;
      case 'education': return <Education setView={setView} />;
      case 'simulator': return <Simulator />;

      default: return <Dashboard setView={setView} />;
    }
  };

  const navItems = [
    { id: 'dashboard', label: 'Inicio', icon: LayoutDashboard },
    { id: 'money', label: 'Dinero', icon: Activity },
    { id: 'automation', label: 'IA', icon: MessageSquare },
    { id: 'profile', label: 'Perfil', icon: User },
  ];

  return (
    <div className="flex h-screen bg-[#F8FAFC] font-sans text-slate-900 overflow-hidden selection:bg-blue-100 selection:text-blue-900">
      <Toast />

      {/* Sidebar - Fixed on desktop, hidden on mobile */}
      <Sidebar 
        currentView={currentView} 
        setView={setView} 
        isMobileMenuOpen={isMobileMenuOpen}
        setIsMobileMenuOpen={setIsMobileMenuOpen}
      />

      {/* Main Content Area */}
      <main className="flex-1 flex flex-col h-full relative overflow-hidden bg-[#F8FAFC]">

        {/* Mobile Header */}
        <header className="lg:hidden bg-white border-b border-slate-200 px-4 py-3 flex items-center justify-between z-20 shrink-0 shadow-[0_2px_8px_-2px_rgba(0,0,0,0.05)]">
          <Logo size="sm" />
          <button 
            onClick={() => setIsMobileMenuOpen(true)}
            className="p-2 text-slate-600 hover:bg-slate-50 hover:text-blue-600 rounded-xl transition-colors"
          >
            <Menu size={24} />
          </button>
        </header>

        {/* Scrollable Content View */}
        <div className="flex-1 overflow-y-auto p-4 md:p-8 scroll-smooth custom-scrollbar">
          <div className="max-w-7xl mx-auto min-h-full">
            {renderView()}
          </div>
        </div>

        {/* Mobile Bottom Nav */}
        <nav className="lg:hidden bg-white border-t border-slate-200 px-6 py-3 flex justify-between items-center z-30 safe-area-bottom shrink-0 shadow-[0_-4px_20px_-10px_rgba(0,0,0,0.1)]">
          {navItems.map((item) => (
            <button
              key={item.id}
              onClick={() => setView(item.id)}
              className={`flex flex-col items-center gap-1.5 transition-all duration-300 ${
                currentView === item.id ? 'text-[#2563EB] scale-105' : 'text-slate-400 hover:text-slate-600'
              }`}
            >
              <item.icon size={22} strokeWidth={currentView === item.id ? 2.5 : 2} />
              <span className="text-[10px] font-bold tracking-wide">{item.label}</span>
            </button>
          ))}
        </nav>
      </main>
    </div>
  );
};

