                 <div className="flex gap-3 mt-2">
                    <button 
                      onClick={() => setIsReportingOrder(null)} 
                      className="flex-1 py-3 text-gray-500 font-bold text-sm hover:bg-gray-50 rounded-xl"
                    >
                      Cancelar
                    </button>
                    <button 
                      onClick={handleReportSubmit}
                      className="flex-1 py-3 bg-red-600 text-white font-bold text-sm rounded-xl shadow-lg shadow-red-500/30 hover:bg-red-700"
                    >
                      Registrar Incidencia
                    </button>
                 </div>
              </div>
           </div>
        </div>
      )}

    </div>
  );
};

import React from 'react';
import { Sparkles } from 'lucide-react';

interface LogoProps {
  size?: 'sm' | 'md' | 'lg' | 'xl';
  showText?: boolean;
  className?: string;
  variant?: 'dark' | 'light';
  animated?: boolean;
}

const Logo: React.FC<LogoProps> = ({ 
  size = 'md', 
  showText = true, 
  className = '', 
  variant = 'light',
  animated = false
}) => {
  const sizeConfig = {
    sm: { icon: 16, container: 'w-8 h-8', text: 'text-lg' },
    md: { icon: 20, container: 'w-10 h-10', text: 'text-xl' },
    lg: { icon: 32, container: 'w-16 h-16', text: 'text-3xl' },
    xl: { icon: 48, container: 'w-24 h-24', text: 'text-5xl' }
  };

  const config = sizeConfig[size];
  const textColor = variant === 'dark' ? 'text-white' : 'text-slate-900';

  return (
    <div className={`flex items-center gap-3 ${className}`}>
      <div 
        className={`
          ${config.container} bg-gradient-to-br from-blue-600 to-emerald-500 rounded-xl flex items-center justify-center text-white shadow-lg shadow-blue-500/20
          ${animated ? 'animate-[bounce_3s_infinite]' : ''}
        `}
      >
        <Sparkles 
          size={config.icon} 
          fill="currentColor" 
          className={animated ? 'animate-[spin_4s_linear_infinite]' : ''} 
        />
      </div>

      {showText && (
        <span className={`font-black tracking-tight ${config.text} ${textColor}`}>
          Labora<span className="text-emerald-500">+</span>
        </span>
      )}
    </div>
  );
};

export default Logo;

