    e.preventDefault();

    // Validations
    if (!formData.nombre || !formData.dni || !formData.email) {
      showNotification('error', 'Nombre, DNI y Email son obligatorios');
      return;
    }

    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
