  const { currentUser, logout, privacyMode, togglePrivacyMode } = useData();

  // Updated Menu Structure - Explicit & Comprehensive
  const managerItems = [
    { section: 'Principal' },
    { id: 'dashboard', label: 'Inicio', icon: LayoutGrid },
    { id: 'all-modules', label: 'Todo (Módulos)', icon: Database },

    { section: 'Gestión' },
    { id: 'people', label: 'Personas (CRM)', icon: Users },
