    { section: 'Herramientas' },
    { id: 'integrations', label: 'Apps de Reparto', icon: Puzzle },
    { id: 'automation', label: 'Automatización (IA)', icon: Cpu },

    { section: 'Sistema' },
    { id: 'settings', label: 'Ajustes & Config', icon: Settings },
  ];

  // Rider Menu
  const riderItems = [
    { section: 'Principal' },
    { id: 'dashboard', label: 'Inicio', icon: LayoutGrid },
    { id: 'all-modules', label: 'Todo', icon: Database },
    { id: 'money', label: 'Finanzas', icon: Wallet },
    { id: 'operations', label: 'Rutas y Mapa', icon: Truck },
    { section: 'Herramientas' },
    { id: 'automation', label: 'Asistente IA', icon: Cpu },
    { id: 'integrations', label: 'Conexiones', icon: Puzzle },
    { id: 'settings', label: 'Ajustes', icon: Settings },
  ];

  const menuItems = currentUser?.role === UserRole.MANAGER || currentUser?.role === UserRole.ADMIN 
    ? managerItems 
    : riderItems;

  const handleNavClick = (viewId: string) => {
    setView(viewId);
    setIsMobileMenuOpen(false);
  };

  return (
    <>
      {/* Mobile Overlay */}
      <div 
        className={`fixed inset-0 bg-slate-900/80 backdrop-blur-sm z-40 lg:hidden transition-opacity duration-300 ${isMobileMenuOpen ? 'opacity-100' : 'opacity-0 pointer-events-none'}`}
        onClick={() => setIsMobileMenuOpen(false)}
      />

      <aside className={`
        fixed lg:static inset-y-0 left-0 z-50 w-72 bg-[#0F172A] text-slate-300 transform transition-transform duration-300 ease-in-out lg:translate-x-0 
        ${isMobileMenuOpen ? 'translate-x-0 shadow-2xl' : '-translate-x-full'}
        flex flex-col border-r border-slate-800
      `}>
        {/* Header */}
        <div className="h-20 flex items-center px-6 border-b border-slate-800">
          {/* Logo is Icon Only in Sidebar to be cleaner */}
          <Logo size="md" variant="dark" showText={false} />

          <button onClick={() => setIsMobileMenuOpen(false)} className="lg:hidden ml-auto p-2 text-slate-400 hover:text-white transition-colors">
             <X size={20} />
          </button>
        </div>

        {/* Navigation */}
        <nav className="flex-1 overflow-y-auto py-6 px-4 space-y-1 custom-scrollbar">
          {menuItems.map((item, idx) => {
            if (item.section) {
              return (
                <div key={`sec-${idx}`} className="px-3 mt-6 mb-2">
                  <span className="text-[10px] font-bold uppercase tracking-wider text-slate-500 font-heading">{item.section}</span>
                </div>
              );
            }

            const isActive = currentView === item.id || currentView.startsWith(item.id + '-');
            return (
              <button
                key={item.id}
                onClick={() => item.id && handleNavClick(item.id)}
                className={`w-full flex items-center gap-3 px-3 py-3 rounded-xl text-sm font-medium transition-all duration-200 group relative ${
                  isActive 
                    ? 'bg-[#2563EB] text-white shadow-lg shadow-blue-900/40' 
                    : 'text-slate-400 hover:text-white hover:bg-slate-800'
                }`}
              >
                {item.icon && <item.icon size={18} className={`transition-colors ${isActive ? 'text-white' : 'text-slate-500 group-hover:text-slate-300'}`} />}
                <span>{item.label}</span>
                {isActive && (
                  <div className="absolute right-3 w-1.5 h-1.5 bg-white rounded-full animate-pulse shadow-[0_0_8px_rgba(255,255,255,0.8)]"></div>
                )}
              </button>
            );
          })}
        </nav>

        {/* Footer Actions */}
        <div className="p-4 border-t border-slate-800 bg-[#0B1120]">
          {/* User Profile Snippet */}
          <div className="flex items-center gap-3 px-1">
            <div className="w-10 h-10 rounded-xl bg-gradient-to-br from-blue-600 to-indigo-700 flex items-center justify-center text-white font-bold shadow-lg border border-slate-700">
              {currentUser?.name.charAt(0).toUpperCase()}
